const SCHEMA_SQL = "-- MaterialFlow schema\n\nCREATE TABLE IF NOT EXISTS customers (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  phone TEXT,\n  email TEXT,\n  billing_address TEXT,\n  notes TEXT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS drivers (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  phone TEXT,\n  truck_label TEXT,\n  pin TEXT NOT NULL,\n  active INTEGER NOT NULL DEFAULT 1,\n  -- Lets this driver submit their own repeat/add-on order requests from the\n  -- delivery board (POST /api/driver/order-requests) — off by default.\n  can_request_orders INTEGER NOT NULL DEFAULT 0,\n  -- Off excludes this driver from the automatic load-balancer\n  -- (autoAssignDelivery) — office can still assign them explicitly by name,\n  -- just never picked automatically. Seeded off for Jared Parrillo and Tom\n  -- Brown at seed time (see lib/seed.js).\n  auto_assign_eligible INTEGER NOT NULL DEFAULT 1,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS materials (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  unit TEXT NOT NULL DEFAULT 'yard',\n  default_price REAL NOT NULL DEFAULT 0,\n  active INTEGER NOT NULL DEFAULT 1\n);\n\nCREATE TABLE IF NOT EXISTS settings (\n  key TEXT PRIMARY KEY,\n  value TEXT\n);\n\nCREATE TABLE IF NOT EXISTS mileage_bands (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  min_miles REAL NOT NULL,\n  max_miles REAL,\n  fee REAL,\n  label TEXT,\n  sort_order INTEGER NOT NULL DEFAULT 0\n);\n\nCREATE TABLE IF NOT EXISTS sms_recipients (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  phone TEXT NOT NULL,\n  carrier TEXT NOT NULL DEFAULT 'verizon',\n  custom_gateway_domain TEXT,\n  active INTEGER NOT NULL DEFAULT 1,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS orders (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  order_number TEXT NOT NULL UNIQUE,\n  customer_id INTEGER NOT NULL REFERENCES customers(id),\n  material_id INTEGER NOT NULL REFERENCES materials(id),\n  quantity REAL NOT NULL,\n  unit TEXT NOT NULL,\n  price_per_unit REAL NOT NULL DEFAULT 0,\n  delivery_address TEXT NOT NULL,\n  distance_miles REAL,\n  delivery_fee REAL NOT NULL DEFAULT 0,\n  sales_tax_rate REAL NOT NULL DEFAULT 0,\n  sales_tax_enabled INTEGER NOT NULL DEFAULT 1,\n  sales_tax_amount REAL NOT NULL DEFAULT 0,\n  total_amount REAL NOT NULL DEFAULT 0,\n  square_invoice_number TEXT,\n  square_invoiced INTEGER NOT NULL DEFAULT 0,\n  square_paid INTEGER NOT NULL DEFAULT 0,\n  requested_date TEXT,\n  requested_window TEXT,\n  notes TEXT,\n  status TEXT NOT NULL DEFAULT 'new', -- new, scheduled, out_for_delivery, delivered, refused, invoiced, cancelled\n  driver_id INTEGER REFERENCES drivers(id),\n  scheduled_date TEXT,\n  scheduled_time TEXT,\n  delivered_at TEXT,\n  driver_notes TEXT,\n  invoice_id INTEGER,\n  payment_collected INTEGER NOT NULL DEFAULT 0, -- driver collected payment (cash/check) at delivery time, ahead of formal invoicing\n  payment_collected_method TEXT,\n  payment_collected_amount REAL,\n  payment_collected_at TEXT,\n  -- job_id: this order is a material load delivered to one of OPD's own job\n  -- sites, not sold to a paying customer — see POST /api/orders, which\n  -- forces a fixed $20/yard, no tax, and a shared internal customer row\n  -- whenever it's set. requested_by_driver_id/source_order_id record a\n  -- driver-submitted repeat/add-on request (POST /api/driver/order-requests)\n  -- and which of that driver's own past orders it was based on.\n  job_id INTEGER REFERENCES jobs(id),\n  requested_by_driver_id INTEGER REFERENCES drivers(id),\n  source_order_id INTEGER REFERENCES orders(id),\n  -- For-hire trucking orders (order_type = 'trucking'): hourly billing, no\n  -- material/quantity picked up front. quantity/price_per_unit/total_amount\n  -- are still reused as hours/hourly-rate/total so invoicing needs no\n  -- changes; material_id points at an auto-created \"For-Hire Trucking\n  -- (Hourly)\" material row so every existing order/material join still\n  -- works. See POST /api/orders and PUT /api/deliveries/:id/{start,deliver}.\n  order_type TEXT NOT NULL DEFAULT 'material',\n  trucking_dropoff_address TEXT,\n  trucking_contact_name TEXT,\n  trucking_contact_phone TEXT,\n  trucking_start_time TEXT,\n  trucking_end_time TEXT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS invoices (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  invoice_number TEXT NOT NULL UNIQUE,\n  customer_id INTEGER NOT NULL REFERENCES customers(id),\n  status TEXT NOT NULL DEFAULT 'draft', -- draft, sent, paid, partial, void\n  subtotal REAL NOT NULL DEFAULT 0,\n  tax_rate REAL NOT NULL DEFAULT 0,\n  tax_amount REAL NOT NULL DEFAULT 0,\n  total REAL NOT NULL DEFAULT 0,\n  amount_paid REAL NOT NULL DEFAULT 0,\n  issued_date TEXT,\n  due_date TEXT,\n  paid_date TEXT,\n  notes TEXT,\n  pay_token TEXT UNIQUE,\n  stripe_checkout_url TEXT,\n  stripe_session_id TEXT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS invoice_items (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  invoice_id INTEGER NOT NULL REFERENCES invoices(id),\n  order_id INTEGER REFERENCES orders(id),\n  description TEXT NOT NULL,\n  quantity REAL NOT NULL,\n  unit TEXT,\n  unit_price REAL NOT NULL,\n  amount REAL NOT NULL\n);\n\nCREATE TABLE IF NOT EXISTS payments (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  invoice_id INTEGER NOT NULL REFERENCES invoices(id),\n  amount REAL NOT NULL,\n  method TEXT NOT NULL, -- stripe, cash, check, ach, other\n  reference TEXT,\n  paid_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS deliveries (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,\n  sequence INTEGER NOT NULL DEFAULT 1,\n  quantity REAL NOT NULL,\n  driver_id INTEGER REFERENCES drivers(id),\n  scheduled_date TEXT,\n  slot_index INTEGER,\n  status TEXT NOT NULL DEFAULT 'unscheduled', -- unscheduled, scheduled, delivered, cancelled\n  delivered_at TEXT,\n  -- This load's own share of the order's total_amount (proportional split by\n  -- quantity at generation time; office can override with an agreed flat\n  -- number, e.g. one that already folds in delivery — see PUT /api/deliveries/:id).\n  amount REAL,\n  payment_collected INTEGER NOT NULL DEFAULT 0, -- driver collected payment (cash/check) for THIS load at delivery time, ahead of formal invoicing\n  payment_collected_method TEXT,\n  payment_collected_amount REAL,\n  payment_collected_at TEXT,\n  -- For-hire trucking (order_type = 'trucking' on the parent order): exactly\n  -- one delivery row per order, no chunking. punch_in_at/punch_out_at are the\n  -- driver's actual clock times; quantity (hours) and amount are computed\n  -- from the gap between them when the driver punches out, then rolled up\n  -- into the order's own quantity/total_amount. See PUT\n  -- /api/deliveries/:id/start and /deliver.\n  punch_in_at TEXT,\n  punch_out_at TEXT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\n-- Driver time clock — one row per shift. At most one \"open\" row\n-- (clock_out IS NULL) per driver, enforced at the route level.\nCREATE TABLE IF NOT EXISTS driver_shifts (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  driver_id INTEGER NOT NULL REFERENCES drivers(id),\n  clock_in TEXT NOT NULL DEFAULT (datetime('now')),\n  clock_out TEXT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\nCREATE INDEX IF NOT EXISTS idx_driver_shifts_driver ON driver_shifts(driver_id, clock_in);\n\n-- ===== Construction Jobs module =====\n\nCREATE TABLE IF NOT EXISTS crews (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  active INTEGER NOT NULL DEFAULT 1,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS equipment (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  type TEXT,\n  active INTEGER NOT NULL DEFAULT 1,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS jobs (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  job_number TEXT NOT NULL UNIQUE,\n  customer_id INTEGER REFERENCES customers(id),\n  customer_name TEXT NOT NULL,\n  customer_phone TEXT,\n  site_address TEXT,\n  scope TEXT,\n  price REAL,\n  target_start_date TEXT,\n  duration_days REAL,\n  crew_id INTEGER REFERENCES crews(id),\n  status TEXT NOT NULL DEFAULT 'inquiry',\n  -- inquiry, estimate_scheduled, quote_sent, accepted, scheduled, deposit_received, in_progress, complete, cancelled\n  permit_number TEXT,\n  next_followup_date TEXT,\n  followup_note TEXT,\n  notes TEXT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS job_equipment (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  job_id INTEGER NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,\n  equipment_id INTEGER NOT NULL REFERENCES equipment(id),\n  start_date TEXT,\n  end_date TEXT\n);\n\nCREATE TABLE IF NOT EXISTS job_checklist_items (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  job_id INTEGER NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,\n  label TEXT NOT NULL,\n  done INTEGER NOT NULL DEFAULT 0,\n  sort_order INTEGER NOT NULL DEFAULT 0,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS job_todos (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  job_id INTEGER NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,\n  description TEXT NOT NULL,\n  category TEXT NOT NULL DEFAULT 'office', -- office, field\n  done INTEGER NOT NULL DEFAULT 0,\n  sort_order INTEGER NOT NULL DEFAULT 0,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS job_permits (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  job_id INTEGER NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,\n  permit_number TEXT,\n  file_name TEXT,\n  file_type TEXT,\n  file_data BLOB,\n  uploaded_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\n-- ---- Estimates: the first half of the estimate -> accepted -> invoice flow\n-- ---- for a job. An estimate always belongs to exactly one job (so it isn't\n-- ---- its own top-level \"customer\" concept the way invoices are) — customer\n-- ---- identity is read through job_id -> jobs.customer_name/phone (and, when\n-- ---- the job is linked to a real customer record, jobs.customer_id) rather\n-- ---- than duplicated here, so a job that only has a free-text customer name\n-- ---- can still get an estimate with no extra setup.\nCREATE TABLE IF NOT EXISTS estimates (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  estimate_number TEXT NOT NULL UNIQUE,\n  job_id INTEGER NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,\n  status TEXT NOT NULL DEFAULT 'draft', -- draft, sent, accepted, declined, converted\n  subtotal REAL NOT NULL DEFAULT 0,\n  tax_rate REAL NOT NULL DEFAULT 0,\n  tax_enabled INTEGER NOT NULL DEFAULT 1,\n  tax_amount REAL NOT NULL DEFAULT 0,\n  total REAL NOT NULL DEFAULT 0,\n  issued_date TEXT,\n  valid_until TEXT,\n  notes TEXT,\n  -- Snapshot of who this goes to, editable independent of the job/customer\n  -- record — same idea as jobs.customer_name/phone — so an estimate can\n  -- show a full \"Bill To\" block even when the job has no linked customer,\n  -- or when the estimate should go to a different address/contact than\n  -- what's on file. Pre-filled from the linked customer record when there\n  -- is one, but always editable on the estimate itself.\n  customer_email TEXT,\n  customer_address TEXT,\n  -- Lets a customer view + accept/decline this one estimate via a plain link\n  -- (see /estimate/:token, mirroring the existing /pay/:token invoice link) —\n  -- no login or full client portal needed for this first version.\n  view_token TEXT UNIQUE,\n  accepted_at TEXT,\n  declined_at TEXT,\n  -- Captured when the customer accepts via the public link: a drawn\n  -- signature (PNG data URL) plus the typed name that goes with it, so an\n  -- accepted estimate can show real proof of sign-off, not just a status\n  -- flag. Null when accepted manually by the office on the customer's\n  -- behalf (e.g. a verbal go-ahead over the phone).\n  signature_data TEXT,\n  signed_name TEXT,\n  converted_invoice_id INTEGER REFERENCES invoices(id),\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS estimate_items (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  estimate_id INTEGER NOT NULL REFERENCES estimates(id) ON DELETE CASCADE,\n  description TEXT NOT NULL,\n  -- Longer explanatory text shown under the item's title on the printed/\n  -- viewed estimate — e.g. \"Excavation\" as the title, with the scope\n  -- details spelled out here.\n  notes TEXT,\n  quantity REAL NOT NULL,\n  unit TEXT,\n  unit_price REAL NOT NULL,\n  amount REAL NOT NULL,\n  sort_order INTEGER NOT NULL DEFAULT 0\n);\n\nCREATE INDEX IF NOT EXISTS idx_estimates_job ON estimates(job_id);\nCREATE INDEX IF NOT EXISTS idx_estimate_items_estimate ON estimate_items(estimate_id);\n\nCREATE INDEX IF NOT EXISTS idx_orders_status ON orders(status);\nCREATE INDEX IF NOT EXISTS idx_orders_driver_date ON orders(driver_id, scheduled_date);\nCREATE INDEX IF NOT EXISTS idx_invoices_customer ON invoices(customer_id);\nCREATE INDEX IF NOT EXISTS idx_deliveries_order ON deliveries(order_id);\nCREATE INDEX IF NOT EXISTS idx_deliveries_driver_date ON deliveries(driver_id, scheduled_date);\nCREATE INDEX IF NOT EXISTS idx_jobs_status ON jobs(status);\nCREATE INDEX IF NOT EXISTS idx_jobs_start_date ON jobs(target_start_date);\nCREATE INDEX IF NOT EXISTS idx_jobs_followup ON jobs(next_followup_date);\nCREATE INDEX IF NOT EXISTS idx_job_equipment_job ON job_equipment(job_id);\nCREATE INDEX IF NOT EXISTS idx_job_equipment_equip_dates ON job_equipment(equipment_id, start_date, end_date);\nCREATE INDEX IF NOT EXISTS idx_job_checklist_job ON job_checklist_items(job_id);\nCREATE INDEX IF NOT EXISTS idx_job_todos_job ON job_todos(job_id);\nCREATE INDEX IF NOT EXISTS idx_job_permits_job ON job_permits(job_id);\n\nCREATE TABLE IF NOT EXISTS users (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  username TEXT NOT NULL UNIQUE,\n  email TEXT,\n  password_hash TEXT NOT NULL,\n  password_salt TEXT NOT NULL,\n  active INTEGER NOT NULL DEFAULT 1,\n  -- 'full' sees everything; 'limited' sees only core dispatch pages plus\n  -- whichever of the flags below are turned on for that account.\n  access_level TEXT NOT NULL DEFAULT 'full',\n  can_view_financials INTEGER NOT NULL DEFAULT 0,\n  can_view_assets INTEGER NOT NULL DEFAULT 0,\n  can_view_realestate INTEGER NOT NULL DEFAULT 0,\n  can_access_admin INTEGER NOT NULL DEFAULT 0,\n  reset_token_hash TEXT,\n  reset_token_expires TEXT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\n-- ---- Equipment / Asset inventory (net-worth tracking; separate from the\n-- ---- scheduling-oriented `equipment` table used by the Jobs module) ----\nCREATE TABLE IF NOT EXISTS assets (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  category TEXT NOT NULL DEFAULT 'equipment', -- equipment, truck, vehicle, tool, other\n  make TEXT,\n  model TEXT,\n  year INTEGER,\n  serial_vin TEXT,\n  purchase_date TEXT,\n  purchase_price REAL,\n  condition TEXT DEFAULT 'good', -- excellent, good, fair, poor\n  location TEXT,\n  notes TEXT,\n  estimated_value REAL,\n  value_updated_at TEXT,\n  debt_balance REAL NOT NULL DEFAULT 0,\n  debt_lender TEXT,\n  debt_notes TEXT,\n  active INTEGER NOT NULL DEFAULT 1,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE INDEX IF NOT EXISTS idx_assets_category ON assets(category);\nCREATE INDEX IF NOT EXISTS idx_assets_active ON assets(active);\n\n-- ---- Real estate / rental portfolio (kept separate from OPD's operating\n-- ---- financials — this revenue flows to the rental holdings account) ----\nCREATE TABLE IF NOT EXISTS properties (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL,\n  address TEXT,\n  purchase_date TEXT,\n  purchase_price REAL,\n  current_value REAL,\n  value_updated_at TEXT,\n  mortgage_balance REAL NOT NULL DEFAULT 0,\n  mortgage_lender TEXT,\n  notes TEXT,\n  active INTEGER NOT NULL DEFAULT 1,\n  -- Standing monthly figures (punched in once, not re-entered every month) —\n  -- these drive the automatic monthly/annual net so a property doesn't need\n  -- every rent payment and bill logged as a transaction to see its net.\n  monthly_rent_income REAL NOT NULL DEFAULT 0,\n  monthly_mortgage_payment REAL NOT NULL DEFAULT 0,\n  monthly_property_tax REAL NOT NULL DEFAULT 0,\n  monthly_insurance REAL NOT NULL DEFAULT 0,\n  monthly_maintenance REAL NOT NULL DEFAULT 0,\n  monthly_other_expenses REAL NOT NULL DEFAULT 0,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS property_income (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  property_id INTEGER NOT NULL REFERENCES properties(id) ON DELETE CASCADE,\n  date TEXT NOT NULL,\n  amount REAL NOT NULL,\n  source TEXT, -- e.g. rent, late fee, deposit\n  notes TEXT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS property_expenses (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  property_id INTEGER NOT NULL REFERENCES properties(id) ON DELETE CASCADE,\n  date TEXT NOT NULL,\n  amount REAL NOT NULL,\n  category TEXT, -- e.g. mortgage, insurance, tax, repair, utility, management\n  payee TEXT,\n  notes TEXT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE INDEX IF NOT EXISTS idx_properties_active ON properties(active);\nCREATE INDEX IF NOT EXISTS idx_property_income_property ON property_income(property_id, date);\nCREATE INDEX IF NOT EXISTS idx_property_expenses_property ON property_expenses(property_id, date);\n\n-- ---- Audit log: every login attempt (success/failure) and every mutating\n-- ---- action taken in the app. Visible only to the super admin (the shared\n-- ---- office login) via GET /api/audit-log / audit-log.html.\nCREATE TABLE IF NOT EXISTS audit_log (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  actor_role TEXT,          -- 'office', 'driver', or NULL (e.g. a failed login with no matching account)\n  actor_name TEXT,          -- display name at the time of the action\n  actor_user_id INTEGER,    -- named office user id, when applicable\n  actor_driver_id INTEGER,  -- driver id, when applicable\n  is_super_admin INTEGER NOT NULL DEFAULT 0,\n  action TEXT NOT NULL,     -- 'login_success', 'login_failed', 'logout', or 'request' for a generic action\n  method TEXT NOT NULL,\n  path TEXT NOT NULL,\n  status INTEGER,\n  detail TEXT,\n  ip TEXT\n);\n\nCREATE INDEX IF NOT EXISTS idx_audit_log_created ON audit_log(created_at);\n";

// DATA_DIR points at a persistent volume mount in production (e.g. Railway) so
// the database survives redeploys. Falls back to the app directory otherwise
// (fine for local runs, but ephemeral on most hosts without a volume).
const DATA_DIR = process.env.DATA_DIR || __dirname;
const DB_PATH = path.join(DATA_DIR, 'materialflow.db');
const db = new DatabaseSync(DB_PATH);
db.exec('PRAGMA foreign_keys = ON;');
db.exec(SCHEMA_SQL);

// Lightweight migrations: CREATE TABLE IF NOT EXISTS above does nothing for a
// table that already exists, so any new column added to the schema after a
// database was first created needs an explicit ADD COLUMN here (guarded so
// it's a no-op once applied). This keeps existing data intact across deploys.
function ensureColumn(table, column, definition) {
  const cols = db.prepare(`PRAGMA table_info(${table})`).all();
  if (!cols.some((c) => c.name === column)) { db.exec(`ALTER TABLE ${table} ADD COLUMN ${column} ${definition}`); return true; }
  return false;
}
(function migrate() {
  ensureColumn('orders', 'distance_miles', 'REAL');
  ensureColumn('orders', 'delivery_fee', 'REAL NOT NULL DEFAULT 0');
  ensureColumn('orders', 'square_invoice_number', 'TEXT');
  ensureColumn('orders', 'square_invoiced', 'INTEGER NOT NULL DEFAULT 0');
  ensureColumn('orders', 'square_paid', 'INTEGER NOT NULL DEFAULT 0');
  ensureColumn('sms_recipients', 'carrier', "TEXT NOT NULL DEFAULT 'verizon'");
  ensureColumn('sms_recipients', 'custom_gateway_domain', 'TEXT');
  ensureColumn('orders', 'sales_tax_rate', 'REAL NOT NULL DEFAULT 0');
  ensureColumn('orders', 'sales_tax_amount', 'REAL NOT NULL DEFAULT 0');
  ensureColumn('orders', 'total_amount', 'REAL NOT NULL DEFAULT 0');
  ensureColumn('users', 'access_level', "TEXT NOT NULL DEFAULT 'full'");
  ensureColumn('users', 'can_view_financials', 'INTEGER NOT NULL DEFAULT 0');
  ensureColumn('users', 'can_view_assets', 'INTEGER NOT NULL DEFAULT 0');
  ensureColumn('users', 'can_view_realestate', 'INTEGER NOT NULL DEFAULT 0');
  ensureColumn('users', 'can_access_admin', 'INTEGER NOT NULL DEFAULT 0');
  ensureColumn('orders', 'payment_collected', 'INTEGER NOT NULL DEFAULT 0');
  ensureColumn('orders', 'payment_collected_method', 'TEXT');
  ensureColumn('orders', 'payment_collected_amount', 'REAL');
  ensureColumn('orders', 'payment_collected_at', 'TEXT');
  ensureColumn('users', 'email', 'TEXT');
  ensureColumn('users', 'reset_token_hash', 'TEXT');
  ensureColumn('users', 'reset_token_expires', 'TEXT');
  // Per-load amount + payment tracking (a multi-load order used to show the
  // FULL order total/payment status on every one of its loads, because those
  // lived only on `orders`). See backfillDeliveryAmounts/backfillDeliveryPayments.
  ensureColumn('deliveries', 'amount', 'REAL');
  ensureColumn('deliveries', 'payment_collected', 'INTEGER NOT NULL DEFAULT 0');
  ensureColumn('deliveries', 'payment_collected_method', 'TEXT');
  ensureColumn('deliveries', 'payment_collected_amount', 'REAL');
  ensureColumn('deliveries', 'payment_collected_at', 'TEXT');
  // For-hire trucking orders — hourly billing, no material/quantity picked up
  // front. order_type distinguishes them from ordinary material orders;
  // quantity/price_per_unit/total_amount are still reused as hours/rate/total
  // so invoicing needs no changes at all. punch_in_at/punch_out_at capture
  // exactly when the driver started and finished so hours are computed from
  // real clock times, not a guess.
  ensureColumn('orders', 'order_type', "TEXT NOT NULL DEFAULT 'material'");
  ensureColumn('orders', 'trucking_dropoff_address', 'TEXT');
  ensureColumn('orders', 'trucking_contact_name', 'TEXT');
  ensureColumn('orders', 'trucking_contact_phone', 'TEXT');
  ensureColumn('orders', 'trucking_start_time', 'TEXT');
  ensureColumn('orders', 'trucking_end_time', 'TEXT');
  ensureColumn('deliveries', 'punch_in_at', 'TEXT');
  ensureColumn('deliveries', 'punch_out_at', 'TEXT');
  // Standing monthly rent/expense figures for the automatic net gain/loss —
  // see computePropertyCashFlow in this file's route section.
  ensureColumn('properties', 'monthly_rent_income', 'REAL NOT NULL DEFAULT 0');
  ensureColumn('properties', 'monthly_mortgage_payment', 'REAL NOT NULL DEFAULT 0');
  ensureColumn('properties', 'monthly_property_tax', 'REAL NOT NULL DEFAULT 0');
  ensureColumn('properties', 'monthly_insurance', 'REAL NOT NULL DEFAULT 0');
  ensureColumn('properties', 'monthly_maintenance', 'REAL NOT NULL DEFAULT 0');
  ensureColumn('properties', 'monthly_other_expenses', 'REAL NOT NULL DEFAULT 0');
  // Lets office toggle sales tax off (or back on) per order — independent of
  // sales_tax_rate, so turning it off doesn't lose the rate to re-apply later.
  ensureColumn('orders', 'sales_tax_enabled', 'INTEGER NOT NULL DEFAULT 1');
  // Links an invoice back to the job (and, when it came from an accepted
  // estimate, the estimate) it was billed from.
  ensureColumn('invoices', 'job_id', 'INTEGER REFERENCES jobs(id)');
  ensureColumn('invoices', 'estimate_id', 'INTEGER REFERENCES estimates(id)');
  ensureColumn('estimates', 'customer_email', 'TEXT');
  ensureColumn('estimates', 'customer_address', 'TEXT');
  ensureColumn('estimates', 'signature_data', 'TEXT');
  ensureColumn('estimates', 'signed_name', 'TEXT');
  ensureColumn('estimate_items', 'notes', 'TEXT');
  ensureColumn('drivers', 'can_request_orders', 'INTEGER NOT NULL DEFAULT 0');
  const addedAutoAssignEligible = ensureColumn('drivers', 'auto_assign_eligible', 'INTEGER NOT NULL DEFAULT 1');
  if (addedAutoAssignEligible) {
    db.exec(`UPDATE drivers SET auto_assign_eligible = 0 WHERE name IN ('Jared Parrillo', 'Tom Brown')`);
  }
  ensureColumn('orders', 'job_id', 'INTEGER REFERENCES jobs(id)');
  ensureColumn('orders', 'requested_by_driver_id', 'INTEGER REFERENCES drivers(id)');
  ensureColumn('orders', 'source_order_id', 'INTEGER REFERENCES orders(id)');
  // A customer's own read-only self-serve link — order history and invoices,
  // pay links reuse the existing /pay/:token flow. Generated lazily the
  // first time office shares it (getOrCreatePortalToken), not up front for
  // every customer, so this stays NULL for most rows until then.
  ensureColumn('customers', 'portal_token', 'TEXT');
  // How the customer's paying for this particular order — office picks one
  // (Cash on Delivery / Invoice / On Account) at creation or any time after.
  // Free text, not an enum, so a one-off arrangement can still be typed in;
  // the order-slip text generator (buildOrderSlipText, orders-database.html)
  // falls back to "Cash on Delivery" when this is blank on an older order.
  ensureColumn('orders', 'payment_terms', 'TEXT');
  // Job Tracker fields — deliberately separate from the existing sales-
  // pipeline `status` column (inquiry/quote_sent/.../complete, still used by
  // the Projects Pipeline widget and crew/equipment scheduling): board_status
  // is the office's day-to-day "what board column is this job in right now"
  // state (planning_stage/in_progress/overdue_balance/awarded/for_bid/
  // job_completed/trash), tracked alongside billed/paid and a free-form
  // job_type — matching the office's own spreadsheet-style Job Tracker
  // (job-tracker.html) and TV job board (job-board.html) one for one.
  ensureColumn('jobs', 'job_type', 'TEXT');
  ensureColumn('jobs', 'board_status', "TEXT NOT NULL DEFAULT 'planning_stage'");
  ensureColumn('jobs', 'billed', 'INTEGER NOT NULL DEFAULT 0');
  ensureColumn('jobs', 'paid', 'INTEGER NOT NULL DEFAULT 0');
  backfillDeliveries();
  backfillDeliveryAmounts();
  backfillDeliveryPayments();
})();

// Orders created before the `deliveries` table existed have no rows there.
// The schedule board and driver app both read from `deliveries`, so give
// every such order exactly one delivery mirroring its own driver/date/status
// — never re-split a legacy order, that would rewrite real delivery history.
function backfillDeliveries() {
  const orphans = db.prepare(`
    SELECT o.id, o.quantity, o.status, o.driver_id, o.scheduled_date, o.delivered_at
    FROM orders o LEFT JOIN deliveries d ON d.order_id = o.id
    WHERE d.id IS NULL
  `).all();
  if (!orphans.length) return;
  for (const o of orphans) {
    let status = 'unscheduled';
    let driverId = null, scheduledDate = null, slotIndex = null, deliveredAt = null;
    if (o.status === 'cancelled') {
      status = 'cancelled';
    } else if (o.status === 'delivered' || o.status === 'invoiced') {
      status = 'delivered'; driverId = o.driver_id; scheduledDate = o.scheduled_date; deliveredAt = o.delivered_at;
    } else if (o.status === 'out_for_delivery') {
      status = 'out_for_delivery'; driverId = o.driver_id; scheduledDate = o.scheduled_date; slotIndex = 0;
    } else if (o.driver_id && o.scheduled_date) {
      status = 'scheduled'; driverId = o.driver_id; scheduledDate = o.scheduled_date; slotIndex = 0;
    }
    db.prepare(
      `INSERT INTO deliveries (order_id, sequence, quantity, driver_id, scheduled_date, slot_index, status, delivered_at) VALUES (?, 1, ?, ?, ?, ?, ?, ?)`
    ).run(o.id, o.quantity, driverId, scheduledDate, slotIndex, status, deliveredAt);
  }
}

// One-time: give every existing delivery row a dollar `amount` (its
// proportional share of its order's total_amount, split by quantity, with
// the last load absorbing the rounding remainder so the loads sum exactly
// to the order total). Only fills rows where amount is still NULL, so it
// never overwrites a manual override made after this has already run once.
function backfillDeliveryAmounts() {
  const orders = db.prepare(`
    SELECT DISTINCT o.id, o.total_amount
    FROM orders o
    JOIN deliveries d ON d.order_id = o.id AND d.amount IS NULL
  `).all();
  for (const o of orders) {
    const loads = db.prepare(
      `SELECT id, quantity FROM deliveries WHERE order_id = ? AND status != 'cancelled' ORDER BY sequence`
    ).all(o.id);
    if (!loads.length) continue;
    const totalQty = loads.reduce((s, l) => s + l.quantity, 0) || 1;
    let assigned = 0;
    loads.forEach((l, i) => {
      let amt;
      if (i === loads.length - 1) {
        amt = Math.round((o.total_amount - assigned) * 100) / 100;
      } else {
        amt = Math.round((o.total_amount * (l.quantity / totalQty)) * 100) / 100;
        assigned += amt;
      }
      db.prepare(`UPDATE deliveries SET amount = ? WHERE id = ?`).run(amt, l.id);
    });
    const cancelled = db.prepare(
      `SELECT id, quantity FROM deliveries WHERE order_id = ? AND status = 'cancelled' AND amount IS NULL`
    ).all(o.id);
    for (const l of cancelled) {
      const amt = Math.round((o.total_amount * (l.quantity / totalQty)) * 100) / 100;
      db.prepare(`UPDATE deliveries SET amount = ? WHERE id = ?`).run(amt, l.id);
    }
  }
}

// One-time: move each order's COD payment-collected record (recorded before
// per-delivery tracking existed) onto that order's first non-cancelled
// delivery, so already-collected payments aren't silently lost. Guarded to
// only copy when the target delivery doesn't already show payment_collected.
function backfillDeliveryPayments() {
  const paidOrders = db.prepare(`
    SELECT id, payment_collected_method, payment_collected_amount, payment_collected_at
    FROM orders WHERE payment_collected = 1
  `).all();
  for (const o of paidOrders) {
    const target = db.prepare(
      `SELECT id, payment_collected FROM deliveries WHERE order_id = ? AND status != 'cancelled' ORDER BY sequence LIMIT 1`
    ).get(o.id);
    if (!target || target.payment_collected) continue;
    db.prepare(
      `UPDATE deliveries SET payment_collected = 1, payment_collected_method = ?, payment_collected_amount = ?, payment_collected_at = ? WHERE id = ?`
    ).run(o.payment_collected_method, o.payment_collected_amount, o.payment_collected_at, target.id);
  }
}

function run(sql, params = []) { return db.prepare(sql).run(...params); }
function get(sql, params = []) { return db.prepare(sql).get(...params); }
function all(sql, params = []) { return db.prepare(sql).all(...params); }

function getSetting(key, fallback = null) {
  const row = get('SELECT value FROM settings WHERE key = ?', [key]);
  return row && row.value !== '' && row.value !== null ? row.value : fallback;
}
function setSetting(key, value) {
  const existing = get('SELECT key FROM settings WHERE key = ?', [key]);
  if (existing) run('UPDATE settings SET value = ? WHERE key = ?', [value, key]);
  else run('INSERT INTO settings (key, value) VALUES (?, ?)', [key, value]);
}

