// only when it actually doesn't fit — using real glyph widths (above)
// rather than a guessed character count, so a table cell never runs into
// the column next to it. Returns the string unchanged when it already fits.
function truncatePdfText(str, font, size, maxWidth) {
  const s = toAsciiSafe(str || '');
  if (pdfTextWidth(s, font, size) <= maxWidth) return s;
  let lo = 0, hi = s.length;
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2);
    if (pdfTextWidth(s.slice(0, mid) + '...', font, size) <= maxWidth) lo = mid; else hi = mid - 1;
  }
  return lo <= 0 ? '...' : s.slice(0, lo) + '...';
}
function buildOrderInvoicePdf(order, customer, company = {}) {
  const companyName = company.name || 'OPD Development Corp';
  const doc = new PdfDoc();
  let y = PDF_PAGE_HEIGHT - 60;
  doc.filledRect(0, PDF_PAGE_HEIGHT - 90, PDF_PAGE_WIDTH, 90, 0.93);
  doc.text(50, y, companyName, { font: 'F2', size: 20 });
  y -= 22;
  doc.text(50, y, 'Delivery Invoice', { font: 'F1', size: 12 });
  y = PDF_PAGE_HEIGHT - 110;

  doc.text(50, y, `Invoice for Order ${order.order_number}`, { font: 'F2', size: 13 });
  const orderDate = formatEasternDate(order.created_at);
  doc.text(PDF_PAGE_WIDTH - 200, y, `Date: ${orderDate}`, { size: 10 });
  y -= 28;

  doc.text(50, y, 'Bill To:', { font: 'F2', size: 10 });
  y -= 14;
  doc.text(50, y, order.customer_name || customer.name || '', { size: 10 });
  y -= 14;
  wrapPdfText(order.delivery_address || '', 60).forEach((line) => { doc.text(50, y, line, { size: 10 }); y -= 14; });
  if (customer.phone) { doc.text(50, y, customer.phone, { size: 10 }); y -= 14; }
  y -= 10;

  doc.hline(50, y, PDF_PAGE_WIDTH - 100);
  y -= 16;
  doc.text(50, y, 'Description', { font: 'F2', size: 10 });
  doc.text(300, y, 'Qty', { font: 'F2', size: 10 });
  doc.text(360, y, 'Unit Price', { font: 'F2', size: 10 });
  doc.text(460, y, 'Amount', { font: 'F2', size: 10 });
  y -= 8;
  doc.hline(50, y, PDF_PAGE_WIDTH - 100);
  y -= 18;

  const qty = Number(order.quantity || 0);
  const price = Number(order.price_per_unit || 0);
  const materialAmount = qty * price;
  doc.text(50, y, truncatePdfText(`${order.material_name || 'Material'} — delivered to ${order.delivery_address || ''}`, 'F1', 10, 242), { size: 10 });
  doc.text(300, y, `${qty} ${order.unit || ''}`, { size: 10 });
  doc.text(360, y, `$${price.toFixed(2)}`, { size: 10 });
  doc.text(460, y, `$${materialAmount.toFixed(2)}`, { size: 10 });
  y -= 18;

  const deliveryFee = Number(order.delivery_fee || 0);
  if (deliveryFee > 0) {
    const label = order.distance_miles ? `Delivery Fee (${order.distance_miles} mi)` : 'Delivery Fee';
    doc.text(50, y, label, { size: 10 });
    doc.text(460, y, `$${deliveryFee.toFixed(2)}`, { size: 10 });
    y -= 18;
  }

  doc.hline(300, y + 6, PDF_PAGE_WIDTH - 350);
  y -= 4;
  doc.text(360, y, 'Subtotal', { size: 10 });
  doc.text(460, y, `$${(materialAmount + deliveryFee).toFixed(2)}`, { size: 10 });
  y -= 16;

  const salesTax = Number(order.sales_tax_amount || 0);
  if (salesTax) {
    doc.text(360, y, `Sales Tax${order.sales_tax_rate ? ` (${order.sales_tax_rate}%)` : ''}`, { size: 10 });
    doc.text(460, y, `$${salesTax.toFixed(2)}`, { size: 10 });
    y -= 16;
  }

  doc.hline(300, y + 8, PDF_PAGE_WIDTH - 350);
  y -= 4;
  const total = Number(order.total_amount || (materialAmount + deliveryFee + salesTax));
  doc.text(360, y, 'Total', { font: 'F2', size: 12 });
  doc.text(460, y, `$${total.toFixed(2)}`, { font: 'F2', size: 12 });
  y -= 26;

  if (order.payment_collected) {
    const collected = Number(order.payment_collected_amount || 0);
    const method = order.payment_collected_method || 'other';
    doc.text(50, y, `Payment received at delivery: $${collected.toFixed(2)} (${method}). Thank you!`, { font: 'F2', size: 10 });
    y -= 20;
  } else {
    doc.text(50, y, 'Please remit payment at your earliest convenience.', { size: 10 });
    y -= 20;
  }

  if (order.notes) {
    y -= 6;
    doc.text(50, y, 'Notes:', { font: 'F2', size: 9 });
    y -= 13;
    wrapPdfText(order.notes, 95).forEach((line) => { doc.text(50, y, line, { size: 9 }); y -= 13; });
  }

  doc.text(50, 50, `Thank you for your business — ${companyName}`, { size: 9 });
  return doc.toBuffer();
}
function buildFinancialReportPdf(summary, orders, opts = {}) {
  const companyName = opts.companyName || 'OPD Development Corp';
  const periodLabel = opts.periodLabel || 'All Time';
  const doc = new PdfDoc();
  const marginX = 50;
  const pageBottom = 60;
  let y;
  function header(title) {
    doc.filledRect(0, PDF_PAGE_HEIGHT - 70, PDF_PAGE_WIDTH, 70, 0.93);
    doc.text(marginX, PDF_PAGE_HEIGHT - 40, companyName, { font: 'F2', size: 18 });
    doc.text(marginX, PDF_PAGE_HEIGHT - 58, title, { size: 11 });
    doc.text(PDF_PAGE_WIDTH - 200, PDF_PAGE_HEIGHT - 40, `Generated ${formatEasternDate(new Date())}`, { size: 9 });
    doc.text(PDF_PAGE_WIDTH - 200, PDF_PAGE_HEIGHT - 54, `Period: ${periodLabel}`, { size: 9 });
    return PDF_PAGE_HEIGHT - 95;
  }
  y = header('Financial Summary');
  doc.text(marginX, y, 'Key Figures', { font: 'F2', size: 12 }); y -= 18;
  const s = summary.stats;
  [
    ['Combined Revenue', `$${Number(s.combinedRevenue).toFixed(2)}`],
    ['Materials Revenue', `$${Number(s.materialsRevenueAllTime).toFixed(2)}`],
    ['Jobs Revenue (Won)', `$${Number(s.jobsRevenueWon).toFixed(2)}`],
    ['Jobs Pipeline Value', `$${Number(s.jobsPipelineValue).toFixed(2)}`],
    ['Orders (all time)', `${s.orderCount}`],
    ['Avg Order Value', `$${Number(s.avgOrderValue).toFixed(2)}`],
  ].forEach(([label, value]) => { doc.text(marginX, y, label, { size: 10 }); doc.text(marginX + 220, y, value, { size: 10 }); y -= 15; });
  y -= 10;
  doc.text(marginX, y, 'Invoices', { font: 'F2', size: 12 }); y -= 18;
  const inv = summary.invoices;
  [
    ['Paid', `$${Number(inv.paidInvoicesTotal).toFixed(2)}`],
    ['Outstanding', `$${Number(inv.outstandingInvoices).toFixed(2)}`],
    ['Overdue Invoices', `${inv.overdueCount}`],
    ['Draft', `$${Number(inv.draftTotal).toFixed(2)}`],
  ].forEach(([label, value]) => { doc.text(marginX, y, label, { size: 10 }); doc.text(marginX + 220, y, value, { size: 10 }); y -= 15; });
  y -= 10;
  doc.text(marginX, y, 'Monthly Revenue', { font: 'F2', size: 12 }); y -= 16;
  doc.text(marginX, y, 'Month', { font: 'F2', size: 9 });
  doc.text(marginX + 120, y, 'Materials', { font: 'F2', size: 9 });
  doc.text(marginX + 220, y, 'Jobs', { font: 'F2', size: 9 });
  doc.text(marginX + 300, y, 'Total', { font: 'F2', size: 9 });
  y -= 6; doc.hline(marginX, y, PDF_PAGE_WIDTH - marginX * 2); y -= 13;
  (summary.monthlyRevenue || []).forEach((r) => {
    doc.text(marginX, y, r.month, { size: 9 });
    doc.text(marginX + 120, y, `$${Number(r.materials).toFixed(2)}`, { size: 9 });
    doc.text(marginX + 220, y, `$${Number(r.jobs).toFixed(2)}`, { size: 9 });
    doc.text(marginX + 300, y, `$${Number(r.total).toFixed(2)}`, { size: 9 });
    y -= 13;
  });
  y -= 8;
  doc.text(marginX, y, 'Revenue by Material', { font: 'F2', size: 12 }); y -= 16;
  (summary.revenueByMaterial || []).slice(0, 12).forEach((r) => {
    doc.text(marginX, y, truncatePdfText(r.material_name, 'F1', 9, 290), { size: 9 });
    doc.text(marginX + 300, y, `$${Number(r.revenue).toFixed(2)}`, { size: 9 });
    y -= 13;
  });
  y -= 8;
  doc.text(marginX, y, 'Top Customers', { font: 'F2', size: 12 }); y -= 16;
  (summary.topCustomers || []).slice(0, 12).forEach((r) => {
    doc.text(marginX, y, truncatePdfText(r.customer_name, 'F1', 9, 290), { size: 9 });
    doc.text(marginX + 300, y, `$${Number(r.revenue).toFixed(2)}`, { size: 9 });
    y -= 13;
  });
  doc.newPage();
  y = header('Order Ledger');
  const cols = [
    { label: 'Date', x: marginX, w: 50 }, { label: 'Order #', x: marginX + 55, w: 88 }, { label: 'Customer', x: marginX + 148, w: 108 },
    { label: 'Material', x: marginX + 261, w: 78 }, { label: 'Qty', x: marginX + 344, w: 42 }, { label: 'Amount', x: marginX + 391, w: 55 }, { label: 'Status', x: marginX + 451, w: 61 },
  ];
  function ledgerTableHeader() {
    cols.forEach((c) => doc.text(c.x, y, c.label, { font: 'F2', size: 9 }));
    y -= 6; doc.hline(marginX, y, PDF_PAGE_WIDTH - marginX * 2); y -= 13;
  }
  ledgerTableHeader();
  (orders || []).forEach((o) => {
    if (y < pageBottom + 20) { doc.newPage(); y = header('Order Ledger (cont.)'); ledgerTableHeader(); }
    doc.text(cols[0].x, y, formatEasternDateShort(o.created_at), { size: 8 });
    doc.text(cols[1].x, y, truncatePdfText(o.order_number || '', 'F1', 8, cols[1].w - 4), { size: 8 });
    doc.text(cols[2].x, y, truncatePdfText(o.customer_name || '', 'F1', 8, cols[2].w - 4), { size: 8 });
    doc.text(cols[3].x, y, truncatePdfText(o.material_name || '', 'F1', 8, cols[3].w - 4), { size: 8 });
    doc.text(cols[4].x, y, truncatePdfText(`${o.quantity} ${o.unit || ''}`, 'F1', 8, cols[4].w - 4), { size: 8 });
    doc.text(cols[5].x, y, truncatePdfText(`$${Number(o.total_amount || 0).toFixed(2)}`, 'F1', 8, cols[5].w - 4), { size: 8 });
    doc.text(cols[6].x, y, truncatePdfText(o.status || '', 'F1', 8, cols[6].w - 4), { size: 8 });
    y -= 12;
  });
  return doc.toBuffer();
}

// Builds a one-page end-of-shift report for a driver's time clock —
// clock in/out times, hours worked, loads delivered, and a payment
// breakdown ending in the cash figure the driver owes the office.
function buildDriverShiftReportPdf(shift, driver, stats, company = {}) {
  const companyName = company.name || 'OPD Development Corp';
  const doc = new PdfDoc();
  const marginX = 50;
  let y = PDF_PAGE_HEIGHT - 60;

  doc.filledRect(0, PDF_PAGE_HEIGHT - 90, PDF_PAGE_WIDTH, 90, 0.93);
  doc.text(marginX, y, companyName, { font: 'F2', size: 20 });
  y -= 22;
  doc.text(marginX, y, 'Driver Shift Report', { font: 'F1', size: 12 });
  y = PDF_PAGE_HEIGHT - 110;

  const shiftDate = formatEasternDate(shift.clock_in);
  doc.text(marginX, y, `${driver.name}${driver.truck_label ? ' — ' + driver.truck_label : ''}`, { font: 'F2', size: 13 });
  doc.text(PDF_PAGE_WIDTH - 200, y, `Date: ${shiftDate}`, { size: 10 });
  y -= 22;

  doc.text(marginX, y, `Clocked in:  ${formatEasternDateTime(shift.clock_in)}`, { size: 10 });
  y -= 15;
  doc.text(marginX, y, `Clocked out: ${shift.clock_out ? formatEasternDateTime(shift.clock_out) : 'still clocked in'}`, { size: 10 });
  y -= 15;
  doc.text(marginX, y, `Hours worked: ${Number(stats.hours || 0).toFixed(2)}`, { size: 10 });
  y -= 24;

  doc.hline(marginX, y, PDF_PAGE_WIDTH - marginX * 2);
  y -= 18;
  doc.text(marginX, y, 'Deliveries This Shift', { font: 'F2', size: 12 });
  y -= 18;
  doc.text(marginX, y, `Completed: ${stats.deliveredCount}   Total Quantity: ${Number(stats.totalQuantity || 0)}`, { size: 10 });
  y -= 20;

  if ((stats.deliveries || []).length) {
    doc.text(marginX, y, 'Order', { font: 'F2', size: 9 });
    doc.text(marginX + 90, y, 'Customer', { font: 'F2', size: 9 });
    doc.text(marginX + 240, y, 'Material', { font: 'F2', size: 9 });
    doc.text(marginX + 340, y, 'Qty', { font: 'F2', size: 9 });
    doc.text(marginX + 400, y, 'Amount', { font: 'F2', size: 9 });
    y -= 6;
    doc.hline(marginX, y, PDF_PAGE_WIDTH - marginX * 2);
    y -= 13;
    stats.deliveries.forEach((d) => {
      if (y < 140) { doc.newPage(); y = PDF_PAGE_HEIGHT - 60; }
      doc.text(marginX, y, truncatePdfText(d.order_number || '', 'F1', 8, 86), { size: 8 });
      doc.text(marginX + 90, y, truncatePdfText(d.customer_name || '', 'F1', 8, 144), { size: 8 });
      doc.text(marginX + 240, y, truncatePdfText(d.material_name || '', 'F1', 8, 94), { size: 8 });
      doc.text(marginX + 340, y, truncatePdfText(`${d.quantity} ${d.unit || ''}`, 'F1', 8, 54), { size: 8 });
      doc.text(marginX + 400, y, d.amount != null ? `$${Number(d.amount).toFixed(2)}` : '—', { size: 8 });
      y -= 12;
    });
    y -= 8;
  }

  if (y < 180) { doc.newPage(); y = PDF_PAGE_HEIGHT - 60; }
  doc.hline(marginX, y, PDF_PAGE_WIDTH - marginX * 2);
  y -= 18;
  doc.text(marginX, y, 'Payments Collected', { font: 'F2', size: 12 });
  y -= 20;
  [
    ['Cash', stats.cashTotal],
    ['Check', stats.checkTotal],
    ['Other', stats.otherTotal],
  ].forEach(([label, value]) => {
    doc.text(marginX, y, label, { size: 10 });
    doc.text(marginX + 200, y, `$${Number(value || 0).toFixed(2)}`, { size: 10 });
    y -= 16;
  });
  y -= 6;
  doc.hline(marginX + 180, y + 6, 150);
  y -= 4;
  doc.text(marginX, y, 'Total Collected', { font: 'F2', size: 11 });
  doc.text(marginX + 200, y, `$${Number(stats.grandCollected || 0).toFixed(2)}`, { font: 'F2', size: 11 });
  y -= 30;

  doc.filledRect(marginX - 10, y - 10, PDF_PAGE_WIDTH - marginX * 2 + 20, 34, 0.88);
  doc.text(marginX, y + 6, 'CASH TO TURN IN TO OFFICE:', { font: 'F2', size: 13 });
  doc.text(marginX + 260, y + 6, `$${Number(stats.cashTotal || 0).toFixed(2)}`, { font: 'F2', size: 13 });

  return doc.toBuffer();
}

const OPEN_ORDER_STATUS_LABELS = {
  new: 'New', scheduled: 'Scheduled', out_for_delivery: 'Out for Delivery', delivered: 'Delivered (awaiting invoice)',
};

// A snapshot of every order still needing action — not yet invoiced,
// cancelled, or refused — for a quick printable "what's still open" report.
function buildOpenOrdersReportPdf(orders, company = {}) {
  const companyName = company.name || 'OPD Development Corp';
  const doc = new PdfDoc();
  const marginX = 50;
  const pageBottom = 60;
  let y;

  function header(title) {
    doc.filledRect(0, PDF_PAGE_HEIGHT - 70, PDF_PAGE_WIDTH, 70, 0.93);
    doc.text(marginX, PDF_PAGE_HEIGHT - 40, companyName, { font: 'F2', size: 18 });
    doc.text(marginX, PDF_PAGE_HEIGHT - 58, title, { size: 11 });
    doc.text(PDF_PAGE_WIDTH - 200, PDF_PAGE_HEIGHT - 40, `Generated ${formatEasternDate(new Date())}`, { size: 9 });
    return PDF_PAGE_HEIGHT - 95;
  }

  y = header('Open Orders Report');

  const counts = {};
  let totalValue = 0;
  orders.forEach((o) => { counts[o.status] = (counts[o.status] || 0) + 1; totalValue += Number(o.total_amount || 0); });

  doc.text(marginX, y, 'Summary', { font: 'F2', size: 12 });
  y -= 18;
  doc.text(marginX, y, `Total open orders: ${orders.length}`, { size: 10 });
  doc.text(marginX + 220, y, `Total value: $${totalValue.toFixed(2)}`, { size: 10 });
  y -= 16;
  Object.keys(OPEN_ORDER_STATUS_LABELS).forEach((status) => {
    if (!counts[status]) return;
    doc.text(marginX, y, `${OPEN_ORDER_STATUS_LABELS[status]}: ${counts[status]}`, { size: 10 });
    y -= 14;
  });
  y -= 10;

  doc.hline(marginX, y, PDF_PAGE_WIDTH - marginX * 2);
  y -= 18;

  const cols = [
    { label: 'Order #', x: marginX, w: 78 },
    { label: 'Status', x: marginX + 78, w: 95 },
    { label: 'Customer', x: marginX + 173, w: 75 },
    { label: 'Material', x: marginX + 248, w: 65 },
    { label: 'Qty', x: marginX + 313, w: 42 },
    { label: 'Driver', x: marginX + 355, w: 55 },
    { label: 'Sched.', x: marginX + 410, w: 42 },
    { label: 'Amount', x: marginX + 452, w: 48 },
  ];
  function tableHeader() {
    cols.forEach((c) => doc.text(c.x, y, c.label, { font: 'F2', size: 9 }));
    y -= 6;
    doc.hline(marginX, y, PDF_PAGE_WIDTH - marginX * 2);
    y -= 13;
  }
  tableHeader();
  if (!orders.length) {
    doc.text(marginX, y, 'Nothing open right now — every order is invoiced, cancelled, or refused.', { size: 10 });
  }
  orders.forEach((o) => {
    // wrapPdfText's own char-count wrapping is just a starting guess — it can
    // still hand back a line too wide for the Status column's real point
    // width (e.g. a long word), so each wrapped line goes through
    // truncatePdfText too as a hard backstop.
    const statusLines = wrapPdfText(OPEN_ORDER_STATUS_LABELS[o.status] || o.status || '', 18)
      .map((line) => truncatePdfText(line, 'F1', 8, cols[1].w - 4));
    const rowHeight = Math.max(12, statusLines.length * 10);
    if (y - rowHeight < pageBottom) {
      doc.newPage();
      y = header('Open Orders Report (cont.)');
      tableHeader();
    }
    doc.text(cols[0].x, y, truncatePdfText(o.order_number || '', 'F1', 8, cols[0].w - 4), { size: 8 });
    statusLines.forEach((line, i) => doc.text(cols[1].x, y - i * 10, line, { size: 8 }));
    doc.text(cols[2].x, y, truncatePdfText(o.customer_name || '', 'F1', 8, cols[2].w - 4), { size: 8 });
    doc.text(cols[3].x, y, truncatePdfText(o.material_name || '', 'F1', 8, cols[3].w - 4), { size: 8 });
    doc.text(cols[4].x, y, truncatePdfText(`${o.quantity}${o.unit ? ' ' + o.unit : ''}`, 'F1', 8, cols[4].w - 4), { size: 8 });
    doc.text(cols[5].x, y, truncatePdfText(o.driver_name || 'Unassign.', 'F1', 8, cols[5].w - 4), { size: 8 });
    doc.text(cols[6].x, y, o.scheduled_date ? formatDateOnlyShort(o.scheduled_date) : '—', { size: 8 });
    doc.text(cols[7].x, y, truncatePdfText(`$${Number(o.total_amount || 0).toFixed(2)}`, 'F1', 8, cols[7].w - 4), { size: 8 });
    y -= rowHeight;
  });

  return doc.toBuffer();
}

// A printable per-driver rundown of one day's stops — one page per driver.
function buildDriverDayReportPdf(dateStr, deliveries, company = {}) {
  const companyName = company.name || 'OPD Development Corp';
  const doc = new PdfDoc();
  const marginX = 50;
  const dateObj = new Date(`${dateStr}T00:00:00`);
  const dateLabel = isNaN(dateObj.getTime())
    ? dateStr
    : dateObj.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });

  function pageHeader(driverName, truckLabel) {
    let py = PDF_PAGE_HEIGHT - 60;
    doc.filledRect(0, PDF_PAGE_HEIGHT - 90, PDF_PAGE_WIDTH, 90, 0.93);
    doc.text(marginX, py, companyName, { font: 'F2', size: 20 });
    py -= 22;
    doc.text(marginX, py, 'Driver Schedule', { font: 'F1', size: 12 });
    py = PDF_PAGE_HEIGHT - 110;
    doc.text(marginX, py, `${driverName}${truckLabel ? ' — ' + truckLabel : ''}`, { font: 'F2', size: 14 });
    doc.text(PDF_PAGE_WIDTH - 230, py, dateLabel, { size: 10 });
    return py - 26;
  }

  const byDriver = new Map();
  const unassigned = [];
  deliveries.forEach((d) => {
    if (!d.driver_id) { unassigned.push(d); return; }
    if (!byDriver.has(d.driver_id)) byDriver.set(d.driver_id, { name: d.driver_name || 'Driver', truck: d.driver_truck, items: [] });
    byDriver.get(d.driver_id).items.push(d);
  });
  const groups = Array.from(byDriver.values()).sort((a, b) => a.name.localeCompare(b.name));
  if (unassigned.length) groups.push({ name: 'Unassigned', truck: null, items: unassigned });

  if (!groups.length) {
    const y = pageHeader('No Deliveries', null);
    doc.text(marginX, y, 'Nothing scheduled for this day.', { size: 11 });
    return doc.toBuffer();
  }

  groups.forEach((g, gi) => {
    if (gi > 0) doc.newPage();
    let y = pageHeader(g.name, g.truck);
    doc.text(marginX, y, `${g.items.length} stop${g.items.length === 1 ? '' : 's'} today`, { font: 'F2', size: 10 });
    y -= 22;
    const items = g.items.slice().sort((a, b) => (a.slot_index ?? 99) - (b.slot_index ?? 99));
    items.forEach((d, i) => {
      if (y < 100) { doc.newPage(); y = PDF_PAGE_HEIGHT - 60; }
      const asap = d.requested_window === 'ASAP' ? '  (ASAP)' : '';
      const load = d.total_deliveries > 1 ? ` (load ${d.sequence}/${d.total_deliveries})` : '';
      doc.text(marginX, y, `${i + 1}. ${d.delivery_address}${asap}`, { font: 'F2', size: 11 });
      y -= 15;
      doc.text(marginX + 14, y, `${d.quantity} ${d.unit} ${d.material_name} for ${d.customer_name} — Order #${d.order_number}${load}`, { size: 10 });
      y -= 15;
      if (d.customer_phone) { doc.text(marginX + 14, y, `Phone: ${d.customer_phone}`, { size: 9 }); y -= 13; }
      if (d.order_notes) {
        wrapPdfText(`Note: ${d.order_notes}`, 90).forEach((line) => { doc.text(marginX + 14, y, line, { size: 9 }); y -= 12; });
      }
      y -= 10;
    });
  });

  return doc.toBuffer();
}

// ---------------------------------------------------------------------------
// Twilio (raw REST calls, no SDK) — SMS order alerts
// ---------------------------------------------------------------------------
function twilioConfigured() { return Boolean(TWILIO_ACCOUNT_SID && TWILIO_AUTH_TOKEN && TWILIO_FROM_NUMBER); }
async function sendSms(to, body) {
  if (!twilioConfigured()) throw new Error('Twilio is not configured.');
  const url = `https://api.twilio.com/2010-04-01/Accounts/${TWILIO_ACCOUNT_SID}/Messages.json`;
  const params = new URLSearchParams({ To: to, From: TWILIO_FROM_NUMBER, Body: body });
  const auth = Buffer.from(`${TWILIO_ACCOUNT_SID}:${TWILIO_AUTH_TOKEN}`).toString('base64');
  const resp = await fetch(url, { method: 'POST', headers: { Authorization: `Basic ${auth}`, 'Content-Type': 'application/x-www-form-urlencoded' }, body: params.toString() });
  const json = await resp.json();
  if (!resp.ok) throw new Error(json.message || 'Twilio send failed');
  return json;
}
async function broadcastSms(recipients, body) {
  const results = await Promise.allSettled(recipients.map((r) => sendSms(r.phone, body)));
  results.forEach((r, i) => { if (r.status === 'rejected') console.error(`SMS to ${recipients[i].name} (${recipients[i].phone}) failed:`, r.reason?.message || r.reason); });
  return results;
}

// ---------------------------------------------------------------------------
// ClickSend (raw REST calls, no SDK) — primary SMS channel. Carrier
// email-to-text gateways (AT&T/Verizon/T-Mobile) were shut down
// industry-wide in 2025 to fight spam abuse, so a real SMS API is needed.
// ---------------------------------------------------------------------------
function clicksendConfigured() { return Boolean(CLICKSEND_USERNAME && CLICKSEND_API_KEY); }
function clicksendE164(phone) {
  const raw = String(phone || '').trim();
  if (raw.startsWith('+')) return raw;
  const digits = raw.replace(/\D/g, '');
  if (digits.length === 10) return `+1${digits}`;
  if (digits.length === 11 && digits.startsWith('1')) return `+${digits}`;
  return `+${digits}`;
}
async function sendClickSendSms(to, body) {
  if (!clicksendConfigured()) throw new Error('ClickSend is not configured (CLICKSEND_USERNAME / CLICKSEND_API_KEY).');
  const auth = Buffer.from(`${CLICKSEND_USERNAME}:${CLICKSEND_API_KEY}`).toString('base64');
  const message = { source: 'materialflow', to: clicksendE164(to), body };
  if (CLICKSEND_FROM) message.from = CLICKSEND_FROM;
  const resp = await fetch('https://rest.clicksend.com/v3/sms/send', {
    method: 'POST',
    headers: { Authorization: `Basic ${auth}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ messages: [message] }),
  });
  let json = null;
  try { json = await resp.json(); } catch (e) { /* no body */ }
  const firstResult = json?.data?.messages?.[0];
  const ok = resp.ok && json && json.response_code === 'SUCCESS' && (!firstResult || firstResult.status !== 'FAILED');
  if (!ok) {
    const detail = firstResult?.status_text || firstResult?.status || json?.response_msg || `HTTP ${resp.status}`;
    throw new Error(`ClickSend send failed: ${detail}`);
  }
  return json;
}
async function broadcastClickSendSms(recipients, body) {
  const results = await Promise.allSettled(recipients.map((r) => sendClickSendSms(r.phone, body)));
  results.forEach((r, i) => { if (r.status === 'rejected') console.error(`ClickSend to ${recipients[i].name} (${recipients[i].phone}) failed:`, r.reason?.message || r.reason); });
  return results;
}

// ---------------------------------------------------------------------------
// Anthropic (raw REST calls, no SDK) — powers "paste a paragraph, get a
// pre-filled order" on New Order. Never creates anything on its own; only
// ever returns best-guess fields for the office to review.
// ---------------------------------------------------------------------------
function anthropicConfigured() { return Boolean(ANTHROPIC_API_KEY); }
async function anthropicExtractJson(systemPrompt, userText, { maxTokens = 700 } = {}) {
  if (!anthropicConfigured()) {
    throw new Error("AI order parsing isn't configured yet — add an ANTHROPIC_API_KEY variable in Railway.");
  }
  const resp = await fetch(ANTHROPIC_API, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'x-api-key': ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01' },
    body: JSON.stringify({ model: ANTHROPIC_MODEL, max_tokens: maxTokens, system: systemPrompt, messages: [{ role: 'user', content: userText }] }),
  });
  const json = await resp.json().catch(() => null);
  if (!resp.ok) {
    const detail = (json && json.error && json.error.message) || resp.statusText;
    throw new Error(`AI parsing failed (${resp.status}): ${detail}. If this model has been retired, set ORDER_PARSE_MODEL in Railway to a current one.`);
  }
  const textBlock = (json.content || []).find((b) => b.type === 'text');
  if (!textBlock) throw new Error('AI parsing failed: empty response from the model.');
  const raw = textBlock.text.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '');
  try { return JSON.parse(raw); } catch (e) { throw new Error("AI parsing failed: the model's response wasn't valid JSON."); }
}

function formatOrderSms(order) {
  const materialCost = Number(order.quantity || 0) * Number(order.price_per_unit || 0);
  const salesTax = order.sales_tax_amount !== undefined && order.sales_tax_amount !== null
    ? Number(order.sales_tax_amount) : materialCost * (Number(order.sales_tax_rate || 0) / 100);
  const total = order.total_amount !== undefined && order.total_amount !== null
    ? Number(order.total_amount) : materialCost + salesTax + Number(order.delivery_fee || 0);
  const orderDate = (order.created_at || '').slice(0, 10) || todayStr();
  const lines = [
    `NEW ORDER - ${order.order_number}`,
    `- Date: ${orderDate}`,
    `- Name: ${order.customer_name}`,
    `- Address: ${order.delivery_address}`,
    `- Material: ${order.material_name}`,
    `- Amount: ${order.quantity} ${order.unit}`,
    `- Total: $${total.toFixed(2)} (incl. $${salesTax.toFixed(2)} sales tax)`,
  ];
  if (order.customer_phone) lines.push(`- Phone: ${order.customer_phone}`);
  if (order.requested_window === 'ASAP') lines.push('- Requested: ASAP');
  else if (order.requested_date) lines.push(`- Requested: ${order.requested_date}${order.requested_window ? ' ' + order.requested_window : ''}`);
  if (order.deliveries && order.deliveries.length > 1) {
    lines.push(`- Split into ${order.deliveries.length} truckloads (${MAX_YARDS_PER_DELIVERY}yd max each):`);
    order.deliveries.forEach((d) => {
      lines.push(`  ${d.sequence}) ${d.quantity} ${order.unit} — ${d.driver_name ? d.driver_name : 'unassigned'}${d.scheduled_date ? ' on ' + d.scheduled_date : ''}`);
    });
  } else if (order.driver_name) {
    lines.push(`- Driver: ${order.driver_name}${order.scheduled_date ? ' on ' + order.scheduled_date : ''}`);
  }
  if (order.delivery_fee) lines.push(`- Delivery fee: $${Number(order.delivery_fee).toFixed(2)}${order.distance_miles ? ` (${order.distance_miles} mi)` : ''}`);
  if (order.notes) lines.push(`- Notes: ${order.notes}`);
  return lines.join('\n');
}
async function notifyNewOrder(order) {
  try {
    const recipients = all('SELECT * FROM sms_recipients WHERE active = 1');
    if (!recipients.length) return;
    const body = formatOrderSms(order);
    if (clicksendConfigured()) {
      await broadcastClickSendSms(recipients, body);
    } else if (twilioConfigured()) {
      await broadcastSms(recipients, body);
    } else if (emailSmsConfigured()) {
      await sendEmailSms(recipients, `New Order ${order.order_number}`, body);
    }
  } catch (e) { console.error('notifyNewOrder failed:', e && e.stack ? e.stack : e); }
}

// ---------------------------------------------------------------------------
// Route table
// ---------------------------------------------------------------------------
const routes = [];

// ---- Audit log -------------------------------------------------------
function clientIp(req) {
  const fwd = req.headers['x-forwarded-for'];
  if (fwd) return String(fwd).split(',')[0].trim();
  return (req.socket && req.socket.remoteAddress) || '';
}
function recordAudit(req, opts) {
  const {
    role = null, name = null, userId = null, driverId = null, superAdmin = false,
    action, method, path, status = null, detail = null,
  } = opts || {};
  try {
    run(
      `INSERT INTO audit_log (actor_role, actor_name, actor_user_id, actor_driver_id, is_super_admin, action, method, path, status, detail, ip)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [role, name, userId || null, driverId || null, superAdmin ? 1 : 0, action, method, path, status, detail, clientIp(req)]
    );
  } catch (e) {
    console.error('audit log write failed:', e && e.stack ? e.stack : e);
  }
}
const AUDIT_SELF_LOGGED = new Set(['/api/login', '/api/logout']);

function on(method, pattern, handler) {
  const paramNames = [];
  const regexStr = pattern.replace(/:([A-Za-z]+)/g, (_, name) => { paramNames.push(name); return '([^/]+)'; });
  const autoLog = method !== 'GET' && !AUDIT_SELF_LOGGED.has(pattern);
  const wrapped = !autoLog ? handler : async (req, res, params, query) => {
    await handler(req, res, params, query);
    const session = getSession(req);
    recordAudit(req, {
      role: session && session.role,
      name: session && session.name,
      userId: session && session.userId,
      driverId: session && session.driverId,
      superAdmin: isSuperAdmin(session),
      action: 'request',
      method,
      path: req.url.split('?')[0],
      status: res.statusCode,
    });
  };
  routes.push({ method, regex: new RegExp(`^${regexStr}$`), paramNames, handler: wrapped });
}

function requireAuth(req, res) {
  const session = getSession(req);
  if (!session) { sendJson(res, 401, { error: 'Not logged in' }); return null; }
  return session;
}
function requireOffice(req, res) {
  const session = requireAuth(req, res);
  if (!session) return null;
  if (session.role !== 'office') { sendJson(res, 403, { error: 'Office access required' }); return null; }
  return session;
}

function isSuperAdmin(session) {
  return !!(session && session.role === 'office' && !session.userId);
}

function getAccess(session) {
  if (!session || session.role !== 'office') return null;
  if (!session.userId) return { full: true };
  const user = get('SELECT access_level, can_view_financials, can_view_assets, can_view_realestate, can_access_admin FROM users WHERE id = ?', [session.userId]);
  if (!user || user.access_level === 'full') return { full: true };
  return {
    full: false,
    can_view_financials: !!user.can_view_financials,
    can_view_assets: !!user.can_view_assets,
    can_view_realestate: !!user.can_view_realestate,
    can_access_admin: !!user.can_access_admin,
  };
}

function requireSection(req, res, flag) {
  const session = requireOffice(req, res);
  if (!session) return null;
  const access = getAccess(session);
  if (access.full || access[flag]) return session;
  sendJson(res, 403, { error: "You don't have permission to access this." });
  return null;
}

function requireSuperAdmin(req, res) {
  const session = requireOffice(req, res);
  if (!session) return null;
  if (isSuperAdmin(session)) return session;
  sendJson(res, 403, { error: 'Only the main office account can do this.' });
  return null;
}

const ORDER_SELECT = `
  SELECT o.*, c.name as customer_name, c.phone as customer_phone, c.billing_address as customer_address,
         m.name as material_name, d.name as driver_name, d.truck_label as driver_truck,
         j.job_number as job_number, rd.name as requested_by_driver_name
  FROM orders o JOIN customers c ON c.id = o.customer_id JOIN materials m ON m.id = o.material_id
  LEFT JOIN drivers d ON d.id = o.driver_id
  LEFT JOIN jobs j ON j.id = o.job_id
  LEFT JOIN drivers rd ON rd.id = o.requested_by_driver_id
`;
const INTERNAL_JOB_CUSTOMER_NAME = 'OPD Job Sites (Internal)';
function getOrCreateInternalJobCustomer() {
  const existing = get('SELECT * FROM customers WHERE name = ?', [INTERNAL_JOB_CUSTOMER_NAME]);
  if (existing) return existing;
  const result = run('INSERT INTO customers (name, notes) VALUES (?, ?)', [
    INTERNAL_JOB_CUSTOMER_NAME,
    "Auto-created placeholder — groups material loads delivered to OPD's own job sites. Not a real customer; see each order's linked Project for the actual destination.",
  ]);
  return get('SELECT * FROM customers WHERE id = ?', [result.lastInsertRowid]);
}
const TRUCKING_MATERIAL_NAME = 'For-Hire Trucking (Hourly)';
// A for-hire trucking order still needs a material_id (orders.material_id is
// NOT NULL and every order listing/invoice/CSV export already displays
// material_name + quantity + unit generically) — so it points at this one
// auto-created placeholder material instead of a real yard/ton material.
// unit 'hour' and default_price 0 are just there for completeness; a
// trucking order always sets its own price_per_unit (the hourly rate) and
// computes its own quantity (hours) from the driver's punch clock.
function getOrCreateTruckingMaterial() {
  const existing = get('SELECT * FROM materials WHERE name = ?', [TRUCKING_MATERIAL_NAME]);
  if (existing) return existing;
  const result = run('INSERT INTO materials (name, unit, default_price, active) VALUES (?, ?, ?, 1)', [TRUCKING_MATERIAL_NAME, 'hour', 0]);
  return get('SELECT * FROM materials WHERE id = ?', [result.lastInsertRowid]);
}
function nextOrderNumberForDate(date) {
  const prefix = `ORD-${date.getFullYear()}${String(date.getMonth() + 1).padStart(2, '0')}${String(date.getDate()).padStart(2, '0')}`;
  const rows = all('SELECT order_number FROM orders WHERE order_number LIKE ?', [`${prefix}%`]);
  let max = 0;
  rows.forEach((r) => {
    const n = parseInt(r.order_number.slice(prefix.length + 1), 10);
    if (!isNaN(n) && n > max) max = n;
  });
  return `${prefix}-${String(max + 1).padStart(3, '0')}`;
}
function nextOrderNumber() { return nextOrderNumberForDate(new Date()); }
function computeOrderTotals(quantity, pricePerUnit, deliveryFee, taxRatePercent, taxEnabled = true) {
  const materialCost = Number(quantity || 0) * Number(pricePerUnit || 0);
  const rate = Number(taxRatePercent || 0);
  const salesTaxAmount = taxEnabled === false ? 0 : money(materialCost * (rate / 100));
  const totalAmount = money(materialCost + salesTaxAmount + Number(deliveryFee || 0));
  return { salesTaxRate: rate, salesTaxAmount, totalAmount };
}
function nextInvoiceNumber() {
  const prefix = `INV-${new Date().getFullYear()}`;
  const count = get('SELECT COUNT(*) as c FROM invoices WHERE invoice_number LIKE ?', [`${prefix}%`]).c;
  return `${prefix}-${String(count + 1).padStart(4, '0')}`;
}

// ---- DELIVERY SPLITTING & AUTO-SCHEDULING ---------------------------------
// A delivery is one truckload — max 20 yards. Orders over that get split
// into multiple deliveries, each auto-placed into the earliest open
// (driver, day, hour-slot). Drivers work a 9-hour day => 9 one-hour slots/day.
const MAX_YARDS_PER_DELIVERY = 20;
const SLOTS_PER_DAY = 9;
const WORKDAY_START_HOUR = 8; // slot 0 = 8:00am, for display only
// The auto-scheduler never picks a slot later than this on its own — slot 7
// = 8 + 7 = 3:00 PM. Later than that always needs a human (schedule page).
const AUTO_ASSIGN_MAX_SLOT = 7;

function splitIntoDeliveryChunks(quantity) {
  const qty = Number(quantity || 0);
  if (qty <= 0) return [];
  const count = Math.ceil(qty / MAX_YARDS_PER_DELIVERY);
  const chunks = [];
  let remaining = qty;
  for (let i = 0; i < count; i++) {
    const chunk = i === count - 1 ? money(remaining) : MAX_YARDS_PER_DELIVERY;
    chunks.push(chunk);
    remaining = money(remaining - MAX_YARDS_PER_DELIVERY);
  }
  return chunks;
}
function slotTimeLabel(slotIndex) {
  if (slotIndex === null || slotIndex === undefined) return null;
  const hour = WORKDAY_START_HOUR + Number(slotIndex);
  const period = hour >= 12 ? 'PM' : 'AM';
  const h12 = ((hour + 11) % 12) + 1;
  return `${h12}:00 ${period}`;
}
function addDays(dateStr, days) {
  const d = new Date(`${dateStr}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}
function usedSlots(driverId, dateStr) {
  return all(`SELECT slot_index FROM deliveries WHERE driver_id = ? AND scheduled_date = ? AND status != 'cancelled'`, [driverId, dateStr])
    .map((r) => r.slot_index).filter((s) => s !== null && s !== undefined);
}
function autoAssignDelivery(deliveryId, opts) {
  const { startDate, preferredDriverId } = opts || {};
  const drivers = preferredDriverId
    ? [get('SELECT * FROM drivers WHERE id = ? AND active = 1', [preferredDriverId])].filter(Boolean)
    : all('SELECT * FROM drivers WHERE active = 1 AND auto_assign_eligible = 1 ORDER BY id');
  if (!drivers.length) return false;
  let date = startDate || todayStr();
  for (let i = 0; i < 120; i++) {
    for (const d of drivers) {
      const usedSet = new Set(usedSlots(d.id, date));
      let openSlot = null;
      for (let s = 0; s <= AUTO_ASSIGN_MAX_SLOT; s++) if (!usedSet.has(s)) { openSlot = s; break; }
      if (openSlot === null) continue;
      run(`UPDATE deliveries SET driver_id = ?, scheduled_date = ?, slot_index = ?, status = 'scheduled', updated_at = datetime('now') WHERE id = ?`,
        [d.id, date, openSlot, deliveryId]);
      return true;
    }
    date = addDays(date, 1);
  }
  return false;
}
// Splits an order's total dollar amount across its truckload chunks in
// proportion to each chunk's share of the total quantity, so a multi-load
// order's loads each show their own slice instead of the full order total.
// The last chunk absorbs the rounding remainder so the loads sum exactly to
// totalAmount.
function splitAmountByChunks(chunks, totalAmount) {
  const totalQty = chunks.reduce((s, q) => s + q, 0) || 1;
  let assigned = 0;
  return chunks.map((qty, idx) => {
    if (idx === chunks.length - 1) return money(totalAmount - assigned);
    const amt = money(totalAmount * (qty / totalQty));
    assigned += amt;
    return amt;
  });
}
// Resizes a truckload to match an order edited after the fact (quantity,
// price, or delivery fee changed). Only acts when there's exactly one
// delivery for the order and it hasn't already gone out — a split order's
// loads, or an already-delivered/refused/cancelled one, are left untouched
// since there's no single unambiguous load to resize; those are adjusted
// manually via the Deliveries table on the order page instead.
function syncSoloDeliveryToOrder(orderId, quantity, totalAmount) {
  const deliveries = all('SELECT * FROM deliveries WHERE order_id = ?', [orderId]);
  if (deliveries.length !== 1) return;
  const only = deliveries[0];
  if (['delivered', 'refused', 'cancelled'].includes(only.status)) return;
  run(`UPDATE deliveries SET quantity = ?, amount = ?, updated_at = datetime('now') WHERE id = ?`,
    [quantity, totalAmount, only.id]);
}
// The reverse direction, for a for-hire trucking order: the hours are only
// known AFTER the driver punches out (see PUT /api/deliveries/:id/deliver),
// so once its one delivery's quantity/amount are computed from the punch
// clock, this rolls them back up into the order's own quantity/
// sales_tax_amount/total_amount — the numbers invoicing actually reads.
function syncTruckingDeliveryToOrder(orderId) {
  const order = get('SELECT * FROM orders WHERE id = ?', [orderId]);
  if (!order) return;
  const delivery = get('SELECT * FROM deliveries WHERE order_id = ? ORDER BY sequence LIMIT 1', [orderId]);
  if (!delivery) return;
  const hours = Number(delivery.quantity || 0);
  const { salesTaxAmount, totalAmount } = computeOrderTotals(hours, order.price_per_unit, 0, order.sales_tax_rate, Boolean(order.sales_tax_enabled));
  run(`UPDATE orders SET quantity = ?, sales_tax_amount = ?, total_amount = ?, updated_at = datetime('now') WHERE id = ?`,
    [hours, salesTaxAmount, totalAmount, orderId]);
}

function generateDeliveriesForOrder(order, opts) {
  const { preferredDriverId, startDate } = opts || {};
  const chunks = splitIntoDeliveryChunks(order.quantity);
  const amounts = splitAmountByChunks(chunks, order.total_amount || 0);
  chunks.forEach((qty, idx) => {
    const result = run(`INSERT INTO deliveries (order_id, sequence, quantity, amount, status) VALUES (?, ?, ?, ?, 'unscheduled')`, [order.id, idx + 1, qty, amounts[idx]]);
    autoAssignDelivery(result.lastInsertRowid, { startDate, preferredDriverId });
  });
}
function recomputeOrderRollup(orderId) {
  const order = get('SELECT * FROM orders WHERE id = ?', [orderId]);
  // 'paid' is a terminal state too (an order marked paid directly, no
  // invoice — see POST /api/orders/:id/mark-paid-direct) — a delivery-level
  // change underneath it must never bounce the order status back to
  // 'delivered' and lose that.
  if (!order || order.status === 'invoiced' || order.status === 'paid') return;
  const deliveries = all('SELECT * FROM deliveries WHERE order_id = ? ORDER BY sequence', [orderId]);
  const notCancelled = deliveries.filter((d) => d.status !== 'cancelled');
  let status;
  let deliveredAt = order.delivered_at;
  if (!notCancelled.length) {
    status = deliveries.length ? 'cancelled' : 'new';
  } else if (notCancelled.every((d) => d.status === 'refused')) {
    status = 'refused';
  } else {
    const active = notCancelled.filter((d) => d.status !== 'refused');
    if (active.every((d) => d.status === 'delivered')) {
      status = 'delivered';
      const dates = active.map((d) => d.delivered_at).filter(Boolean).sort();
      if (dates.length) deliveredAt = dates[dates.length - 1];
    } else if (active.some((d) => d.driver_id && d.scheduled_date)) {
      status = 'scheduled';
    } else {
      status = 'new';
    }
  }
  const scheduledOnes = notCancelled.filter((d) => d.status !== 'refused' && d.driver_id && d.scheduled_date)
    .sort((a, b) => (a.scheduled_date === b.scheduled_date ? a.sequence - b.sequence : (a.scheduled_date < b.scheduled_date ? -1 : 1)));
  const driverId = scheduledOnes.length ? scheduledOnes[0].driver_id : null;
  const scheduledDate = scheduledOnes.length ? scheduledOnes[0].scheduled_date : null;
  run(`UPDATE orders SET status = ?, driver_id = ?, scheduled_date = ?, delivered_at = ?, updated_at = datetime('now') WHERE id = ?`,
    [status, driverId, scheduledDate, deliveredAt, orderId]);
}
function revertDeliveryToScheduled(deliveryId) {
  const d = get('SELECT * FROM deliveries WHERE id = ?', [deliveryId]);
  if (!d) return;
  const newStatus = (d.driver_id && d.scheduled_date) ? 'scheduled' : 'unscheduled';
  const order = get('SELECT order_type FROM orders WHERE id = ?', [d.order_id]);
  if (order && order.order_type === 'trucking') {
    // Reopening a trucking job clears its punch clock and computed
    // hours/amount too — punching in and out again produces the real bill
    // rather than leaving stale numbers from the previous attempt. Any
    // payment already collected against the old (now-zeroed) hours is
    // cleared too, so the driver isn't shown "Paid $X" for a job that no
    // longer has hours or an amount behind it.
    run(`UPDATE deliveries SET status = ?, delivered_at = NULL, punch_in_at = NULL, punch_out_at = NULL, quantity = 0, amount = 0, payment_collected = 0, payment_collected_method = NULL, payment_collected_amount = NULL, payment_collected_at = NULL, updated_at = datetime('now') WHERE id = ?`, [newStatus, deliveryId]);
    syncTruckingDeliveryToOrder(d.order_id);
  } else {
    run(`UPDATE deliveries SET status = ?, delivered_at = NULL, updated_at = datetime('now') WHERE id = ?`, [newStatus, deliveryId]);
  }
}
function appendDriverNote(orderId, note) {
  if (!note) return;
  const order = get('SELECT driver_notes FROM orders WHERE id = ?', [orderId]);
  const combined = order && order.driver_notes ? `${order.driver_notes}\n${note}` : note;
  run(`UPDATE orders SET driver_notes = ?, updated_at = datetime('now') WHERE id = ?`, [combined, orderId]);
}

// ---- AUTH ----
on('POST', '/api/login', async (req, res) => {
  const body = await readJsonBody(req);
  if (body.role === 'office') {
    const username = (body.username || '').trim().toLowerCase();
    if (username) {
      const user = get('SELECT * FROM users WHERE username = ? AND active = 1', [username]);
      if (user && verifyPassword(body.password || '', user.password_hash, user.password_salt)) {
        createSession(res, { role: 'office', name: user.name, userId: user.id });
        recordAudit(req, { role: 'office', name: user.name, userId: user.id, action: 'login_success', method: 'POST', path: '/api/login', status: 200, detail: `Logged in as ${user.name}` });
        return sendJson(res, 200, { ok: true, role: 'office', name: user.name });
      }
      recordAudit(req, { role: 'office', name: username, action: 'login_failed', method: 'POST', path: '/api/login', status: 401, detail: `Failed office login for username "${username}"` });
      return sendJson(res, 401, { error: 'Incorrect username or password' });
    }
    if (body.password === OFFICE_PASSWORD) {
      createSession(res, { role: 'office', name: 'Dispatch' });
      recordAudit(req, { role: 'office', name: 'Dispatch', superAdmin: true, action: 'login_success', method: 'POST', path: '/api/login', status: 200, detail: 'Logged in as the main office account' });
      return sendJson(res, 200, { ok: true, role: 'office', name: 'Dispatch' });
    }
    recordAudit(req, { role: 'office', action: 'login_failed', method: 'POST', path: '/api/login', status: 401, detail: 'Failed main office login attempt (wrong password)' });
    return sendJson(res, 401, { error: 'Incorrect password' });
  }
  if (body.role === 'driver') {
    if (!body.driverId) return sendJson(res, 400, { error: 'Pick a driver.' });
    const driver = get('SELECT * FROM drivers WHERE id = ? AND active = 1', [body.driverId]);
    if (driver && driver.pin === String(body.pin || '')) {
      createSession(res, { role: 'driver', driverId: driver.id, name: driver.name });
      recordAudit(req, { role: 'driver', name: driver.name, driverId: driver.id, action: 'login_success', method: 'POST', path: '/api/login', status: 200, detail: `Driver logged in: ${driver.name}` });
      return sendJson(res, 200, { ok: true, role: 'driver', name: driver.name, driverId: driver.id });
    }
    recordAudit(req, { role: 'driver', name: driver ? driver.name : null, driverId: body.driverId, action: 'login_failed', method: 'POST', path: '/api/login', status: 401, detail: 'Failed driver login attempt (wrong PIN)' });
    return sendJson(res, 401, { error: 'Incorrect PIN' });
  }
  recordAudit(req, { action: 'login_failed', method: 'POST', path: '/api/login', status: 400, detail: `Unknown login role "${body.role}"` });
  return sendJson(res, 400, { error: 'Unknown role' });
});
on('POST', '/api/logout', async (req, res) => {
  const session = getSession(req);
  if (session) {
    recordAudit(req, {
      role: session.role, name: session.name, userId: session.userId, driverId: session.driverId,
      superAdmin: isSuperAdmin(session), action: 'logout', method: 'POST', path: '/api/logout', status: 200, detail: 'Logged out',
    });
  }
  destroySession(req, res);
  sendJson(res, 200, { ok: true });
});
on('GET', '/api/me', async (req, res) => {
  const session = getSession(req);
  if (!session) return sendJson(res, 200, { loggedIn: false });
  const access = getAccess(session);
  let canRequestOrders = false;
  if (session.role === 'driver' && session.driverId) {
    const driver = get('SELECT can_request_orders FROM drivers WHERE id = ?', [session.driverId]);
    canRequestOrders = !!(driver && driver.can_request_orders);
  }
  sendJson(res, 200, { loggedIn: true, ...session, access, isSuperAdmin: isSuperAdmin(session), canRequestOrders });
});
on('GET', '/api/audit-log', async (req, res, params, query) => {
  if (!requireSuperAdmin(req, res)) return;
  const limit = Math.min(Number(query.limit) || 100, 500);
  const offset = Math.max(Number(query.offset) || 0, 0);
  const conditions = [];
  const args = [];
  if (query.who === 'super_admin') { conditions.push("actor_role = 'office' AND is_super_admin = 1"); }
  else if (query.who === 'named_user') { conditions.push("actor_role = 'office' AND is_super_admin = 0"); }
  else if (query.who === 'driver') { conditions.push("actor_role = 'driver'"); }
  if (query.action) { conditions.push('action = ?'); args.push(query.action); }
  if (query.q) {
    const like = `%${query.q}%`;
    conditions.push('(actor_name LIKE ? OR path LIKE ? OR detail LIKE ?)');
    args.push(like, like, like);
  }
  const where = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';
  const rows = all(`SELECT * FROM audit_log ${where} ORDER BY id DESC LIMIT ? OFFSET ?`, [...args, limit, offset]);
  rows.forEach((r) => { r.created_at_display = formatEasternDateTime(r.created_at); });
  const total = get(`SELECT COUNT(*) as count FROM audit_log ${where}`, args).count;
  sendJson(res, 200, { rows, total });
});

// ---- FORGOT / RESET PASSWORD ----
const RESET_TOKEN_TTL_MS = 60 * 60 * 1000;
function hashResetToken(token) { return crypto.createHash('sha256').update(token).digest('hex'); }
on('POST', '/api/forgot-password', async (req, res) => {
  const b = await readJsonBody(req);
  const username = (b.username || '').trim().toLowerCase();
  const genericMsg = { ok: true, message: 'If that account exists and has an email on file, a reset link has been sent.' };
  if (!username) return sendJson(res, 200, genericMsg);
  const user = get('SELECT * FROM users WHERE username = ? AND active = 1', [username]);
  if (user && user.email && emailConfigured()) {
    const token = crypto.randomBytes(32).toString('hex');
    const expires = new Date(Date.now() + RESET_TOKEN_TTL_MS).toISOString();
    run('UPDATE users SET reset_token_hash = ?, reset_token_expires = ? WHERE id = ?', [hashResetToken(token), expires, user.id]);
    const baseUrl = `${req.headers['x-forwarded-proto'] || 'http'}://${req.headers.host}`;
    try {
      await sendMail({
        to: user.email,
        subject: 'Reset your OPD Development Corp password',
        text: `Hi ${user.name},\n\nSomeone requested a password reset for your account (${user.username}).\n\nReset your password here (link expires in 1 hour):\n${baseUrl}/reset-password.html?token=${token}\n\nIf you didn't request this, you can safely ignore this email — your password will stay the same.`,
      });
    } catch (err) {}
  }
  sendJson(res, 200, genericMsg);
});
on('POST', '/api/reset-password', async (req, res) => {
  const b = await readJsonBody(req);
  const token = (b.token || '').trim();
  const password = b.password || '';
  if (!token) return sendJson(res, 400, { error: 'Missing reset token.' });
  if (password.length < 6) return sendJson(res, 400, { error: 'Password must be at least 6 characters' });
  const tokenHash = hashResetToken(token);
  const user = get('SELECT * FROM users WHERE reset_token_hash = ? AND active = 1', [tokenHash]);
  if (!user || !user.reset_token_expires || new Date(user.reset_token_expires).getTime() < Date.now()) {
    return sendJson(res, 400, { error: 'This reset link is invalid or has expired. Request a new one.' });
  }
  const { hash, salt } = hashPassword(password);
  run('UPDATE users SET password_hash = ?, password_salt = ?, reset_token_hash = NULL, reset_token_expires = NULL WHERE id = ?',
    [hash, salt, user.id]);
  sendJson(res, 200, { ok: true });
});

// ---- DASHBOARD ----
on('GET', '/api/dashboard/summary', async (req, res) => {
  const session = requireOffice(req, res);
  if (!session) return;
  const access = getAccess(session);
  const counts = get(`SELECT SUM(CASE WHEN status='new' THEN 1 ELSE 0 END) as new_orders, SUM(CASE WHEN status='scheduled' THEN 1 ELSE 0 END) as scheduled_orders, SUM(CASE WHEN status='delivered' THEN 1 ELSE 0 END) as delivered_orders, SUM(CASE WHEN status='invoiced' THEN 1 ELSE 0 END) as invoiced_orders FROM orders`);
  const invoiceCounts = get(`SELECT SUM(CASE WHEN status IN ('sent','partial') THEN total - amount_paid ELSE 0 END) as outstanding, SUM(CASE WHEN status='paid' THEN total ELSE 0 END) as paid_total FROM invoices`);
  const todaysDeliveries = all(`${DELIVERY_SELECT} WHERE del.scheduled_date = ? AND del.status != 'cancelled' ORDER BY del.driver_id, del.slot_index IS NULL, del.slot_index`, [todayStr()])
    .map((r) => ({ ...r, slot_time: slotTimeLabel(r.slot_index) }));
  const needsAttention = all(`${ORDER_SELECT} WHERE o.status = 'new' ORDER BY o.created_at ASC LIMIT 25`).map((o) => {
    const created = parseUtcSqlDate(o.created_at);
    const hoursWaiting = created ? Math.max(0, Math.round((Date.now() - created.getTime()) / 3600000)) : null;
    return { id: o.id, order_number: o.order_number, customer_name: o.customer_name, material_name: o.material_name, quantity: o.quantity, unit: o.unit, job_number: o.job_number, created_at: o.created_at, hours_waiting: hoursWaiting };
  });
  const customerCount = get('SELECT COUNT(*) as c FROM customers').c;
  const driverRows = all('SELECT id, active FROM drivers');
  const activeDriverCount = driverRows.filter((d) => d.active).length;
  const deliveriesByDriverToday = all(`SELECT d.name as driver_name, COUNT(*) as count FROM deliveries del JOIN drivers d ON d.id = del.driver_id WHERE del.scheduled_date = ? AND del.status != 'cancelled' GROUP BY del.driver_id ORDER BY count DESC`, [todayStr()]);
  const recentDriverRequests = get(`SELECT COUNT(*) as c FROM orders WHERE requested_by_driver_id IS NOT NULL AND created_at >= datetime('now', '-7 days')`).c;
  const result = { counts, invoiceCounts, todaysDeliveries, needsAttention, customerCount, driverActivity: { activeDriverCount, deliveriesByDriverToday, recentDriverRequests } };
  if (access.full || access.can_view_assets) {
    const a = computeAssetsSummary();
    result.assetsSummary = { total_assets: a.total_assets, net_worth: a.net_worth };
  }
  if (access.full || access.can_view_realestate) {
    const p = computePropertiesSummary();
    result.propertiesSummary = { total_properties: p.total_properties, net_equity: p.net_equity, monthly_net: p.monthly_net };
  }
  if (access.full || access.can_view_financials) {
    const fin = computeFinancialSummary(1);
    const thisMonth = fin.monthlyRevenue[fin.monthlyRevenue.length - 1] || { total: 0 };
    result.financialSnapshot = { revenue_this_month: thisMonth.total, outstanding_invoices: fin.invoices.outstandingInvoices, overdue_invoices: fin.invoices.overdueCount };
  }
  sendJson(res, 200, result);
});

// ---- GLOBAL SEARCH ----
// One box, four tables — customers, orders, invoices, and projects — each
// matched on the field an office user would actually type (name/phone,
// order number/address, invoice number, job number/customer). Capped at 6
// rows per category so the dropdown stays short; this is a jump-to-record
// tool, not a reporting query.
on('GET', '/api/search', async (req, res, params, query) => {
  if (!requireOffice(req, res)) return;
  const q = String((query && query.q) || '').trim();
  if (q.length < 2) return sendJson(res, 200, { results: [] });
  const like = `%${q}%`;
  const customers = all(`SELECT id, name, phone FROM customers WHERE name LIKE ? OR phone LIKE ? ORDER BY name LIMIT 6`, [like, like]);
  const orders = all(`SELECT o.id, o.order_number, c.name as customer_name FROM orders o LEFT JOIN customers c ON c.id = o.customer_id WHERE o.order_number LIKE ? OR o.delivery_address LIKE ? ORDER BY o.created_at DESC LIMIT 6`, [like, like]);
  const invoices = all(`SELECT i.id, i.invoice_number, c.name as customer_name FROM invoices i JOIN customers c ON c.id = i.customer_id WHERE i.invoice_number LIKE ? ORDER BY i.created_at DESC LIMIT 6`, [like]);
  const jobs = all(`SELECT id, job_number, customer_name FROM jobs WHERE job_number LIKE ? OR customer_name LIKE ? ORDER BY created_at DESC LIMIT 6`, [like, like]);
  const results = [
    ...customers.map((c) => ({ type: 'Customer', label: c.name, sub: c.phone || '', href: `/customer-detail.html?id=${c.id}` })),
    ...orders.map((o) => ({ type: 'Order', label: o.order_number, sub: o.customer_name || '', href: `/order-detail.html?id=${o.id}` })),
    ...invoices.map((i) => ({ type: 'Invoice', label: i.invoice_number, sub: i.customer_name || '', href: `/invoice-detail.html?id=${i.id}` })),
    ...jobs.map((j) => ({ type: 'Project', label: j.job_number, sub: j.customer_name || '', href: `/job-detail.html?id=${j.id}` })),
  ];
  sendJson(res, 200, { results });
});

