// A customer's own token is generated the first time office asks for it
// (not up front for every customer on creation) and then kept forever —
// re-sharing the link later returns the same URL rather than invalidating
// whatever the customer already bookmarked.
function getOrCreatePortalToken(customerId) {
  const c = get('SELECT portal_token FROM customers WHERE id = ?', [customerId]);
  if (!c) return null;
  if (c.portal_token) return c.portal_token;
  const token = crypto.randomBytes(16).toString('hex');
  run('UPDATE customers SET portal_token = ? WHERE id = ?', [token, customerId]);
  return token;
}
on('POST', '/api/customers/:id/portal-link', async (req, res, params) => {
  if (!requireOffice(req, res)) return;
  const token = getOrCreatePortalToken(params.id);
  if (!token) return sendJson(res, 404, { error: 'Customer not found' });
  const baseUrl = `${req.headers['x-forwarded-proto'] || 'https'}://${req.headers.host}`;
  sendJson(res, 200, { token, url: `${baseUrl}/portal/${token}` });
});

