  if (!requireSection(req, res, 'can_access_admin')) return;
  const b = await readJsonBody(req);
  if (!b.name || !b.pin) return sendJson(res, 400, { error: 'Name and PIN are required' });
  const result = run('INSERT INTO drivers (name, phone, truck_label, pin, can_request_orders, auto_assign_eligible) VALUES (?, ?, ?, ?, ?, ?)', [b.name, b.phone || null, b.truck_label || null, String(b.pin), b.can_request_orders ? 1 : 0, b.auto_assign_eligible !== undefined ? (b.auto_assign_eligible ? 1 : 0) : 1]);
