on('PUT', '/api/drivers/:id', async (req, res, params) => {
  if (!requireSection(req, res, 'can_access_admin')) return;
  const b = await readJsonBody(req);
  const existing = get('SELECT * FROM drivers WHERE id = ?', [params.id]);
  if (!existing) return sendJson(res, 404, { error: 'Driver not found' });
  const name = b.name !== undefined ? b.name : existing.name;
  const phone = b.phone !== undefined ? b.phone : existing.phone;
  const truck_label = b.truck_label !== undefined ? b.truck_label : existing.truck_label;
  const pin = b.pin !== undefined && b.pin !== '' ? String(b.pin) : existing.pin;
  const active = b.active !== undefined ? (b.active ? 1 : 0) : existing.active;
  const can_request_orders = b.can_request_orders !== undefined ? (b.can_request_orders ? 1 : 0) : existing.can_request_orders;
  const auto_assign_eligible = b.auto_assign_eligible !== undefined ? (b.auto_assign_eligible ? 1 : 0) : existing.auto_assign_eligible;
  run('UPDATE drivers SET name = ?, phone = ?, truck_label = ?, pin = ?, active = ?, can_request_orders = ?, auto_assign_eligible = ? WHERE id = ?', [name, phone, truck_label, pin, active, can_request_orders, auto_assign_eligible, params.id]);
  sendJson(res, 200, get('SELECT id, name, phone, truck_label, pin, active, can_request_orders, auto_assign_eligible FROM drivers WHERE id = ?', [params.id]));
});
on('DELETE', '/api/drivers/:id', async (req, res, params) => {
  if (!requireSuperAdmin(req, res)) return;
  const inUse = get('SELECT COUNT(*) as c FROM orders WHERE driver_id = ?', [params.id]).c;
  if (inUse > 0) return sendJson(res, 400, { error: `Can't delete — ${inUse} order(s) are assigned to this driver. Mark them inactive instead.` });
  run('DELETE FROM drivers WHERE id = ?', [params.id]);
  sendJson(res, 200, { ok: true });
});
on('POST', '/api/driver/order-requests', async (req, res) => {
  const session = getSession(req);
  if (!session || session.role !== 'driver') return sendJson(res, 403, { error: 'Drivers only' });
  const driver = get('SELECT * FROM drivers WHERE id = ?', [session.driverId]);
  if (!driver || !driver.can_request_orders) {
    return sendJson(res, 403, { error: "You don't have permission to request orders yet — ask the office to turn this on for you." });
  }
  const b = await readJsonBody(req);
  const source = get(`${ORDER_SELECT} WHERE o.id = ?`, [b.source_order_id]);
  if (!source) return sendJson(res, 404, { error: 'Original order not found' });
  if (source.driver_id !== driver.id) {
    return sendJson(res, 403, { error: 'You can only request a repeat or add-on based on one of your own deliveries.' });
  }
  const quantity = Number(b.quantity);
  if (!quantity || quantity <= 0) return sendJson(res, 400, { error: 'Enter a quantity.' });
  const { salesTaxRate, salesTaxAmount, totalAmount } = computeOrderTotals(
    quantity, source.price_per_unit, 0, source.sales_tax_rate, !!source.sales_tax_enabled
  );
  const orderNumber = nextOrderNumber();
  const notesText = b.notes ? `Requested by driver ${driver.name}: ${b.notes}` : `Requested by driver ${driver.name}.`;
  const result = run(
    `INSERT INTO orders (order_number, customer_id, material_id, quantity, unit, price_per_unit, delivery_address, delivery_fee, sales_tax_rate, sales_tax_enabled, sales_tax_amount, total_amount, requested_date, requested_window, notes, requested_by_driver_id, source_order_id, status) VALUES (?, ?, ?, ?, ?, ?, ?, 0, ?, ?, ?, ?, ?, 'ASAP', ?, ?, ?, 'new')`,
    [orderNumber, source.customer_id, source.material_id, quantity, source.unit, source.price_per_unit, source.delivery_address, salesTaxRate, source.sales_tax_enabled, salesTaxAmount, totalAmount, todayStr(), notesText, driver.id, source.id]
  );
  const orderId = result.lastInsertRowid;
  generateDeliveriesForOrder({ id: orderId, quantity, total_amount: totalAmount }, { startDate: todayStr(), preferredDriverId: driver.id });
  recomputeOrderRollup(orderId);
  const newOrder = get(`${ORDER_SELECT} WHERE o.id = ?`, [orderId]);
  notifyNewOrder(newOrder);
  recordAudit(req, {
    role: 'driver', name: driver.name, driverId: driver.id, action: 'order_request', method: 'POST', path: '/api/driver/order-requests', status: 201,
    detail: `Requested ${quantity} ${source.unit} ${source.material_name} — repeat/add-on of ${source.order_number}${b.notes ? `: ${b.notes}` : ''}`,
  });
  sendJson(res, 201, newOrder);
});

// ---- USER ACCOUNTS (named office logins — username + password) -----------
const USER_SELECT = 'SELECT id, name, username, email, active, access_level, can_view_financials, can_view_assets, can_view_realestate, can_access_admin, created_at FROM users ORDER BY name';

function accessFieldsFromBody(b, existing) {
  const access_level = b.access_level === 'limited' ? 'limited' : (b.access_level === 'full' ? 'full' : (existing ? existing.access_level : 'full'));
  const flag = (key) => b[key] !== undefined ? (b[key] ? 1 : 0) : (existing ? existing[key] : 0);
  return {
    access_level,
    can_view_financials: flag('can_view_financials'),
    can_view_assets: flag('can_view_assets'),
    can_view_realestate: flag('can_view_realestate'),
    can_access_admin: flag('can_access_admin'),
  };
}

on('GET', '/api/users', async (req, res) => { if (!requireSuperAdmin(req, res)) return; sendJson(res, 200, all(USER_SELECT)); });
on('POST', '/api/users', async (req, res) => {
  if (!requireSuperAdmin(req, res)) return;
  const b = await readJsonBody(req);
  const name = (b.name || '').trim();
  const username = (b.username || '').trim().toLowerCase();
  const password = b.password || '';
  if (!name || !username || !password) return sendJson(res, 400, { error: 'Name, username, and password are required' });
  if (password.length < 6) return sendJson(res, 400, { error: 'Password must be at least 6 characters' });
  const clash = get('SELECT id FROM users WHERE username = ?', [username]);
  if (clash) return sendJson(res, 400, { error: 'That username is already taken' });
  const email_ = (b.email || '').trim().toLowerCase() || null;
  const { hash, salt } = hashPassword(password);
  const acc = accessFieldsFromBody(b, null);
  const result = run(`INSERT INTO users
    (name, username, email, password_hash, password_salt, access_level, can_view_financials, can_view_assets, can_view_realestate, can_access_admin)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [name, username, email_, hash, salt, acc.access_level, acc.can_view_financials, acc.can_view_assets, acc.can_view_realestate, acc.can_access_admin]);
  sendJson(res, 201, get(USER_SELECT.replace('ORDER BY name', 'WHERE id = ?'), [result.lastInsertRowid]));
});
on('PUT', '/api/users/:id', async (req, res, params) => {
  if (!requireSuperAdmin(req, res)) return;
  const b = await readJsonBody(req);
  const existing = get('SELECT * FROM users WHERE id = ?', [params.id]);
  if (!existing) return sendJson(res, 404, { error: 'Account not found' });
  const name = b.name !== undefined && b.name !== '' ? b.name.trim() : existing.name;
  let username = existing.username;
  if (b.username !== undefined && b.username !== '') {
    username = b.username.trim().toLowerCase();
    const clash = get('SELECT id FROM users WHERE username = ? AND id != ?', [username, params.id]);
    if (clash) return sendJson(res, 400, { error: 'That username is already taken' });
  }
  const active = b.active !== undefined ? (b.active ? 1 : 0) : existing.active;
  const email_ = b.email !== undefined ? ((b.email || '').trim().toLowerCase() || null) : existing.email;
  let password_hash = existing.password_hash;
  let password_salt = existing.password_salt;
  if (b.password) {
    if (b.password.length < 6) return sendJson(res, 400, { error: 'Password must be at least 6 characters' });
    const { hash, salt } = hashPassword(b.password);
    password_hash = hash;
    password_salt = salt;
  }
  const acc = accessFieldsFromBody(b, existing);
  run(`UPDATE users SET name = ?, username = ?, email = ?, active = ?, password_hash = ?, password_salt = ?,
    access_level = ?, can_view_financials = ?, can_view_assets = ?, can_view_realestate = ?, can_access_admin = ? WHERE id = ?`,
    [name, username, email_, active, password_hash, password_salt,
      acc.access_level, acc.can_view_financials, acc.can_view_assets, acc.can_view_realestate, acc.can_access_admin, params.id]);
  sendJson(res, 200, get(USER_SELECT.replace('ORDER BY name', 'WHERE id = ?'), [params.id]));
});
on('DELETE', '/api/users/:id', async (req, res, params) => {
  if (!requireSuperAdmin(req, res)) return;
  run('DELETE FROM users WHERE id = ?', [params.id]);
  sendJson(res, 200, { ok: true });
});

// ---- EQUIPMENT / ASSET INVENTORY (net-worth tracking) ---------------------
// Deliberately separate from the `equipment` table used by the Jobs module
// for crew/equipment scheduling — this is financial record-keeping, not
// operational scheduling, and the two are not merged or synced.

on('GET', '/api/assets', async (req, res, params, query) => {
  if (!requireSection(req, res, 'can_view_assets')) return;
  const showAll = query && query.all === '1';
  sendJson(res, 200, showAll
    ? all('SELECT * FROM assets ORDER BY category, name')
    : all('SELECT * FROM assets WHERE active = 1 ORDER BY category, name'));
});

function computeAssetsSummary() {
  const rows = all('SELECT category, estimated_value, debt_balance FROM assets WHERE active = 1');
  const totalValue = money(rows.reduce((sum, r) => sum + (r.estimated_value || 0), 0));
  const totalDebt = money(rows.reduce((sum, r) => sum + (r.debt_balance || 0), 0));
  const byCategory = {};
  rows.forEach((r) => {
    const cat = r.category || 'other';
    if (!byCategory[cat]) byCategory[cat] = { category: cat, count: 0, value: 0, debt: 0 };
    byCategory[cat].count += 1;
    byCategory[cat].value += (r.estimated_value || 0);
    byCategory[cat].debt += (r.debt_balance || 0);
  });
  const by_category = Object.values(byCategory)
    .map((c) => ({ category: c.category, count: c.count, value: money(c.value), debt: money(c.debt), equity: money(c.value - c.debt) }))
    .sort((a, b) => b.value - a.value);
  return { total_assets: rows.length, total_value: totalValue, total_debt: totalDebt, net_worth: money(totalValue - totalDebt), by_category };
}
on('GET', '/api/assets/summary', async (req, res) => {
  if (!requireSection(req, res, 'can_view_assets')) return;
  sendJson(res, 200, computeAssetsSummary());
});

on('GET', '/api/assets/:id', async (req, res, params) => {
  if (!requireSection(req, res, 'can_view_assets')) return;
  const row = get('SELECT * FROM assets WHERE id = ?', [params.id]);
  if (!row) return sendJson(res, 404, { error: 'Asset not found' });
  sendJson(res, 200, row);
});

