on('GET', '/api/orders', async (req, res, params, query) => {
  if (!requireAuth(req, res)) return;
  const clauses = [], args = [];
  if (query.status) { clauses.push('o.status = ?'); args.push(query.status); }
  if (query.driver_id) { clauses.push('o.driver_id = ?'); args.push(query.driver_id); }
  if (query.date) { clauses.push('o.scheduled_date = ?'); args.push(query.date); }
  if (query.job_id) { clauses.push('o.job_id = ?'); args.push(query.job_id); }
  const where = clauses.length ? `WHERE ${clauses.join(' AND ')}` : '';
  sendJson(res, 200, all(`${ORDER_SELECT} ${where} ORDER BY o.created_at DESC`, args));
});
on('GET', '/api/orders/export.csv', async (req, res) => {
  if (!requireOffice(req, res)) return;
  const rows = all(`${ORDER_SELECT} ORDER BY o.created_at DESC`);
  const csv = toCsv(rows, [
    { label: 'order_number', value: 'order_number' }, { label: 'date', value: (r) => (r.created_at || '').slice(0, 10) },
    { label: 'customer_name', value: 'customer_name' }, { label: 'customer_phone', value: 'customer_phone' },
    { label: 'material_name', value: 'material_name' }, { label: 'quantity', value: 'quantity' }, { label: 'unit', value: 'unit' },
    { label: 'price_per_unit', value: 'price_per_unit' }, { label: 'delivery_address', value: 'delivery_address' },
    { label: 'delivery_fee', value: 'delivery_fee' }, { label: 'sales_tax_amount', value: 'sales_tax_amount' },
    { label: 'total_amount', value: 'total_amount' }, { label: 'status', value: 'status' }, { label: 'driver_name', value: 'driver_name' },
    { label: 'scheduled_date', value: 'scheduled_date' }, { label: 'delivered_at', value: 'delivered_at' },
    // Payment is now tracked per-load (see DELIVERY_SELECT) since a
    // multi-load order can be paid across several loads/methods — sum
    // across this order's non-cancelled deliveries rather than reading the
    // order-level column, which nothing writes to any more.
    { label: 'payment_collected_amount', value: (r) => orderPaymentSummary(r.id).amount },
    { label: 'payment_collected_method', value: (r) => orderPaymentSummary(r.id).method },
    { label: 'invoice_id', value: 'invoice_id' }, { label: 'notes', value: 'notes' },
  ]);
  sendCsv(res, `Orders-${todayStr()}.csv`, csv);
});

const OPEN_ORDER_STATUSES = ['new', 'scheduled', 'out_for_delivery', 'delivered'];
