  sendXlsx(res, 'assets-template.xlsx', buildXlsxTemplate(['name', 'category', 'make', 'model', 'year', 'serial_vin', 'purchase_date', 'purchase_price', 'condition', 'location', 'estimated_value', 'debt_balance', 'debt_lender', 'notes']));
